-- ============================================
-- UT-L1 FINAL ASSESSMENT (module 12, step 2) — 40 questions
-- ============================================
-- Idempotent: clear any previously-seeded questions for this final-assessment step first.
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L1' AND m."orderIndex" = 12 AND ls."orderIndex" = 2 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, q.question, q.options::jsonb, q."correctAnswer", q.explanation, q.category, 'UT', 'Level I', q.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('UT (Ultrasonic Testing) mendeteksi diskontinuitas terutama menggunakan:',
   '["Gelombang suara frekuensi tinggi","Sinar-X / gamma","Medan magnet","Cairan penetran"]', 0,
   'UT memakai gelombang ultrasonik (suara frekuensi tinggi) yang dipantulkan oleh diskontinuitas. Sinar-X (RT), medan magnet (MT), dan penetran (PT) adalah metode lain.', 'basics', 'easy'),
  ('Rentang frekuensi yang umum dipakai pada UT industri adalah:',
   '["1–10 kHz","100–500 GHz","0.5–25 MHz","50–100 Hz"]', 2,
   'UT umumnya bekerja pada 0.5–25 MHz. Frekuensi lebih tinggi memberi resolusi lebih baik tetapi penetrasi lebih rendah.', 'physics', 'easy'),
  ('Hubungan antara kecepatan (c), frekuensi (f), dan panjang gelombang (λ):',
   '["c = f × λ","c = f / λ","c = f + λ","f = c × λ"]', 0,
   'Kecepatan = frekuensi × panjang gelombang (c = fλ). Ini hubungan fundamental gelombang.', 'physics', 'easy'),
  ('Bila frekuensi dinaikkan (kecepatan tetap), panjang gelombang akan:',
   '["Meningkat","Menurun","Tetap","Menjadi nol"]', 1,
   'Karena λ = c/f, menaikkan f menurunkan λ (hubungan terbalik). Panjang gelombang lebih pendek = resolusi lebih baik.', 'physics', 'easy'),
  ('Kecepatan gelombang longitudinal pada baja kira-kira:',
   '["1480 m/s","340 m/s","3230 m/s","5900 m/s"]', 3,
   'Baja: longitudinal ≈5900 m/s, shear ≈3230 m/s. 1480 m/s adalah air, 340 m/s udara.', 'materials', 'medium'),
  ('Jenis gelombang yang membutuhkan medium padat (tidak merambat dalam cairan/gas) adalah:',
   '["Shear (transversal)","Longitudinal","Gelombang suara di udara","Gelombang tekan"]', 0,
   'Shear wave butuh modulus geser yang tidak dimiliki cairan/gas, sehingga hanya merambat di padatan. Longitudinal bisa merambat di semua medium.', 'physics', 'medium'),
  ('Kecepatan suara dalam air kira-kira:',
   '["340 m/s","1480 m/s","5900 m/s","6320 m/s"]', 1,
   'Air ≈1480 m/s (penting pada immersion testing). 340 m/s udara, 5900 m/s baja, 6320 m/s aluminum.', 'materials', 'easy'),
  ('Hukum Snell pada UT digunakan untuk:',
   '["Mengukur kekerasan material","Mengukur suhu benda uji","Menghitung sudut refraksi pada interface","Menghitung densitas"]', 2,
   'Hukum Snell menghubungkan sudut datang dan sudut bias saat gelombang melewati interface dua medium dengan kecepatan berbeda.', 'physics', 'medium'),
  ('Pada first critical angle (sudut kritis pertama):',
   '["Semua gelombang dipantulkan total","Gelombang longitudinal terbias 90° dan hanya shear yang masuk material","Kecepatan suara berlipat ganda","Probe berhenti bekerja"]', 1,
   'Di sudut kritis pertama, gelombang longitudinal terbias ke 90° (sepanjang permukaan) sehingga hanya gelombang shear yang merambat ke dalam material — dasar angle beam.', 'physics', 'hard'),
  ('Mode conversion paling mungkin terjadi pada:',
   '["Material homogen tanpa batas","Ruang hampa","Normal beam pada permukaan datar","Interface dengan sudut datang miring"]', 3,
   'Pada interface dengan sudut, energi dapat berpindah antara gelombang longitudinal dan shear (mode conversion) sesuai hukum Snell.', 'physics', 'medium'),
  ('Near field (zona Fresnel) adalah:',
   '["Daerah dekat transducer di mana intensitas beam berfluktuasi","Daerah tepat di belakang cacat","Ujung terjauh benda uji","Lapisan couplant"]', 0,
   'Near field adalah daerah dekat transducer di mana interferensi gelombang membuat intensitas berfluktuasi; sizing cacat sulit akurat di zona ini.', 'physics', 'medium'),
  ('Atenuasi suara paling besar terjadi pada material dengan:',
   '["Permukaan halus","Densitas rendah","Butir (grain) kasar","Butir halus"]', 2,
   'Material grain kasar (mis. cast iron, austenitic stainless) memiliki banyak batas butir yang menyebarkan (scatter) suara → atenuasi tinggi.', 'physics', 'medium'),
  ('Tampilan A-scan menunjukkan:',
   '["Amplitudo vs waktu tempuh (time of flight)","Peta tampak atas","Penampang melintang","Citra 3D volumetrik"]', 0,
   'A-scan menampilkan amplitudo (sumbu vertikal) terhadap waktu tempuh (sumbu horizontal), memperlihatkan echo dari reflektor.', 'equipment', 'easy'),
  ('Fungsi couplant pada contact testing adalah:',
   '["Mendinginkan transducer","Menghilangkan celah udara antara probe dan benda uji","Mewarnai permukaan","Menambah atenuasi"]', 1,
   'Couplant (air, oli, gel) mengisi celah udara antara probe dan permukaan agar transmisi ultrasonik efisien (impedansi lebih cocok).', 'techniques', 'easy'),
  ('Elemen transducer UT menghasilkan ultrasound melalui efek:',
   '["Fotolistrik","Termoelektrik","Efek Hall","Piezoelektrik"]', 3,
   'Kristal piezoelektrik mengubah tegangan listrik menjadi getaran mekanik (dan sebaliknya), menghasilkan & menerima ultrasound.', 'equipment', 'medium'),
  ('C-scan menampilkan:',
   '["Peta tampak-atas (plan view) lokasi reflektor","Amplitudo vs waktu","Spektrum frekuensi","Hanya backwall echo"]', 0,
   'C-scan menyajikan peta tampak-atas posisi reflektor pada bidang scan, berguna untuk memetakan luasan cacat seperti laminasi.', 'equipment', 'medium'),
  ('Material backing/damping pada probe berfungsi:',
   '["Menambah dead zone","Menaikkan tegangan tanpa batas","Meredam getaran kristal sehingga pulsa lebih pendek dan resolusi lebih baik","Mengubah kecepatan suara material"]', 2,
   'Backing meredam ring-down kristal sehingga pulsa lebih pendek → resolusi aksial lebih baik (meski sedikit menurunkan sensitivitas).', 'equipment', 'hard'),
  ('Probe dual-element (TR) sering dipakai untuk:',
   '["Inspeksi sangat dalam","Mengurangi dead zone pada material tipis / near-surface","Mengukur suhu","Menggantikan couplant"]', 1,
   'Probe TR memisahkan elemen transmit dan receive sehingga dead zone berkurang — cocok untuk material tipis, pengukuran ketebalan, dan deteksi near-surface.', 'equipment', 'medium'),
  ('PRF (Pulse Repetition Frequency) yang terlalu tinggi dapat menyebabkan:',
   '["Wrap-around / ghost echo dari pulsa sebelumnya","Couplant cepat mengering","Kristal pecah","Kecepatan suara berubah"]', 0,
   'PRF terlalu tinggi membuat echo dari pulsa sebelumnya muncul pada siklus berikut (wrap-around/ghost), menyesatkan interpretasi.', 'equipment', 'hard'),
  ('Untuk inspeksi sambungan las (weld) baja, teknik utama yang umum dipakai:',
   '["Immersion saja","Through-transmission saja","Straight beam saja","Angle beam (shear wave)"]', 3,
   'Geometri las dan orientasi cacat (mis. lack of fusion, crack) menuntut angle beam shear wave agar beam mengenai cacat secara efektif.', 'techniques', 'medium'),
  ('DAC singkatan dari:',
   '["Distance Amplitude Correction","Digital Amplitude Control","Defect Analysis Chart","Dual Axis Calibration"]', 0,
   'DAC (Distance Amplitude Correction) mengompensasi penurunan amplitudo akibat beam spread dan atenuasi seiring bertambahnya jarak.', 'calibration', 'medium'),
  ('Blok kalibrasi yang umum untuk angle beam adalah:',
   '["Pelat datar polos","Silinder kosong","Blok IIW","Koin referensi"]', 2,
   'Blok IIW (International Institute of Welding) lazim untuk kalibrasi angle beam: cek exit point, refracted angle, dan range.', 'calibration', 'medium'),
  ('Tujuan utama reference/calibration block adalah:',
   '["Menyimpan alat","Mengkalibrasi alat dan menetapkan sensitivitas","Membersihkan probe","Mengukur suhu"]', 1,
   'Blok referensi dipakai untuk mengkalibrasi peralatan, memverifikasi kinerja, dan menetapkan level sensitivitas yang tepat.', 'calibration', 'easy'),
  ('Mengatur range (skala layar) pada straight beam biasanya memakai:',
   '["Multiple back-wall echo dari tebal yang diketahui","Warna permukaan","Berat benda uji","Suhu ruangan"]', 0,
   'Echo back-wall berulang dari ketebalan diketahui dipakai untuk mengatur range/velocity agar posisi reflektor terbaca akurat.', 'calibration', 'medium'),
  ('Exit point (titik keluar beam) probe angle beam diverifikasi pada blok IIW menggunakan:',
   '["Lubang 1.5 mm","Skala desibel","Backing material","Radius lengkung 100 mm"]', 3,
   'Puncak echo dari radius 100 mm blok IIW menandai posisi exit point pada wedge probe.', 'calibration', 'medium'),
  ('Refracted angle (sudut bias) aktual probe angle beam diverifikasi dengan:',
   '["Menimbang probe","Menandai posisi puncak echo pada blok IIW lalu mencocokkan ke skala sudut","Mengukur frekuensi","Melihat warna couplant"]', 1,
   'Posisi puncak echo dari reflektor referensi pada blok IIW dibandingkan dengan skala sudut untuk memastikan sudut bias sebenarnya (bisa berbeda dari nominal).', 'calibration', 'medium'),
  ('Kalibrasi alat UT sebaiknya dilakukan:',
   '["Hanya sekali seumur alat","Hanya setelah alat rusak","Sebelum dan sesudah inspeksi serta pada interval yang ditentukan","Tidak perlu sama sekali"]', 2,
   'Kalibrasi diverifikasi sebelum & sesudah pekerjaan (dan pada interval per prosedur) untuk memastikan hasil tetap valid; jika drift, inspeksi diulang.', 'calibration', 'easy'),
  ('SDH (side-drilled hole) dan FBH (flat-bottom hole) digunakan sebagai:',
   '["Reflektor referensi untuk menyusun kurva DAC / sensitivitas","Sumber radiasi","Jenis couplant","Sumber panas"]', 0,
   'SDH dan FBH adalah reflektor buatan dengan ukuran/kedalaman diketahui untuk menyusun DAC dan menetapkan level sensitivitas referensi.', 'calibration', 'hard'),
  ('Perbedaan pulse-echo dan through-transmission:',
   '["Keduanya selalu memakai 2 probe","Through-transmission mengukur waktu pantul","Pulse-echo butuh 3 probe","Pulse-echo 1 probe (kirim+terima); through-transmission 2 probe berhadapan"]', 3,
   'Pulse-echo memakai satu probe yang mengirim & menerima pantulan; through-transmission memakai dua probe berhadapan dan menilai energi yang menembus.', 'techniques', 'medium'),
  ('Pada immersion testing, media kopling utamanya adalah:',
   '["Air","Gel kental","Udara","Gemuk (grease)"]', 0,
   'Pada immersion, benda uji dan probe terendam air yang menjadi media kopling, memberi scanning konsisten tanpa kontak langsung.', 'techniques', 'easy'),
  ('Dead zone pada pulse-echo disebabkan oleh:',
   '["Couplant berlebih","Lebar pulsa awal dan ring-down transducer","Material terlalu tipis","Frekuensi terlalu rendah"]', 1,
   'Dead zone muncul akibat lebar pulsa awal dan ring-down transducer; echo near-surface tidak dapat dibedakan dari pulsa awal di zona ini.', 'techniques', 'medium'),
  ('Cacat laminasi (paralel terhadap permukaan) paling baik dideteksi dengan:',
   '["Angle beam 70°","Surface wave","Straight beam (normal)","Hanya VT"]', 2,
   'Laminasi paralel permukaan memantulkan beam normal dengan baik; straight beam memperlihatkan loss back-wall dan echo laminasi.', 'techniques', 'medium'),
  ('Surface preparation sebelum contact UT bertujuan:',
   '["Menghilangkan karat/scale agar kopling baik","Menambah atenuasi","Mengubah kecepatan suara","Mewarnai cacat"]', 0,
   'Permukaan kasar/berkarat menghalangi kopling dan menyebabkan loss sinyal; permukaan bersih & rata memastikan transmisi ultrasonik yang andal.', 'techniques', 'easy'),
  ('Reflektor yang memberikan echo paling kuat adalah:',
   '["Void bulat kecil","Permukaan datar tegak lurus terhadap beam","Porositas tersebar","Inklusi miring"]', 1,
   'Reflektor datar yang tegak lurus beam memantulkan suara langsung kembali ke probe sehingga menghasilkan echo terkuat.', 'defects', 'medium'),
  ('Lack of fusion pada sidewall las paling efektif dideteksi dengan:',
   '["Angle beam dengan sudut sesuai geometri bevel","Straight beam dari atas","Surface (Rayleigh) wave","Hanya immersion C-scan"]', 0,
   'Lack of fusion sidewall berorientasi sesuai bevel; angle beam dengan sudut yang tepat membuat beam mengenai bidang cacat secara tegak lurus.', 'defects', 'hard'),
  ('Porositas (banyak pori kecil) pada A-scan biasanya tampak sebagai:',
   '["Satu echo besar tunggal","Tidak ada echo sama sekali","Banyak echo kecil tak beraturan disertai penurunan backwall sebagian","Backwall yang menguat"]', 2,
   'Pori-pori kecil menyebarkan suara ke berbagai arah → banyak echo kecil acak dan backwall sebagian menurun karena scattering.', 'defects', 'medium'),
  ('Penurunan/ hilangnya backwall echo disertai munculnya indikasi baru menandakan:',
   '["Couplant berlebih","Frekuensi salah","Probe rusak","Adanya reflektor/diskontinuitas yang menghalangi atau menyebarkan beam"]', 3,
   'Reflektor internal memantulkan/menyebarkan sebagian energi sehingga backwall melemah sementara muncul echo cacat — indikasi klasik adanya diskontinuitas.', 'interpretation', 'hard'),
  ('Untuk membedakan sinyal geometri (mis. fillet, undercut) dari sinyal cacat, inspector sebaiknya:',
   '["Scan dari beberapa arah dan korelasikan dengan geometri benda uji","Menaikkan gain hingga maksimum","Mengabaikan semua sinyal kecil","Langsung mengganti probe"]', 0,
   'Sinyal geometri berperilaku konsisten dengan bentuk benda; scanning multi-arah dan korelasi geometri membantu memastikan apakah indikasi nyata atau pantulan geometri.', 'interpretation', 'medium'),
  ('Resolusi aksial (memisahkan dua reflektor berdekatan dalam arah kedalaman) membaik dengan:',
   '["Pulsa panjang","Pulsa pendek / frekuensi lebih tinggi","Frekuensi sangat rendah","Couplant lebih tebal"]', 1,
   'Pulsa pendek (sering dari frekuensi lebih tinggi dan damping baik) meningkatkan resolusi aksial sehingga dua reflektor berdekatan dapat dibedakan.', 'physics', 'medium'),
  ('Wedge (sepatu) pada probe angle beam berfungsi:',
   '["Mendinginkan probe","Sebagai sumber suara utama","Membiaskan beam ke sudut tertentu melalui mode conversion","Menyimpan data hasil inspeksi"]', 2,
   'Wedge memiringkan beam sehingga terjadi refraksi/mode conversion menghasilkan gelombang shear pada sudut bias tertentu (mis. 45°/60°/70°) di dalam material.', 'equipment', 'medium')
) AS q(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L1' AND m."orderIndex" = 12 AND ls."orderIndex" = 2 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ============================================
-- MT-L1 FINAL ASSESSMENT (module 12, step 2) — 40 questions
-- ============================================
-- Idempotent: clear any previously-seeded questions for this final-assessment step first.
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L1' AND m."orderIndex" = 12 AND ls."orderIndex" = 2 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, q.question, q.options::jsonb, q."correctAnswer", q.explanation, q.category, 'MT', 'Level I', q.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Magnetic Particle Testing (MT) hanya dapat diterapkan pada jenis material apa?',
   '["Semua logam termasuk aluminum dan copper","Material ferromagnetik seperti baja karbon dan besi cor","Material non-logam seperti keramik dan plastik","Stainless steel austenitic"]', 1,
   'MT mengandalkan kemampuan material mengonsentrasikan flux magnet, sehingga hanya material ferromagnetik (baja karbon, baja paduan rendah, besi cor) yang bisa diinspeksi. Aluminum, copper, dan austenitic stainless steel memiliki permeabilitas relatif ~1 sehingga tidak cocok.', 'Prinsip MT', 'easy'),
  ('Seberapa kecil lebar crack permukaan yang masih mampu dideteksi oleh MT yang sensitif?',
   '["Sekitar 1 mikron","Minimum 1 mm","Minimum 5 mm","Hanya crack yang terlihat mata telanjang"]', 0,
   'MT (khususnya wet fluorescent) sangat sensitif terhadap retak halus permukaan dan mampu mendeteksi crack selebar sekitar 1 mikron — jauh lebih halus daripada yang bisa dilihat mata telanjang. Inilah keunggulan utama MT untuk material ferromagnetik.', 'Prinsip MT', 'easy'),
  ('Jenis cacat apa yang paling utama dapat dideteksi oleh MT?',
   '["Cacat di tengah penampang material yang tebal","Cacat permukaan dan near-surface","Hanya cacat internal volumetric","Penipisan dinding akibat korosi internal"]', 1,
   'MT efektif untuk cacat permukaan (surface) dan near-surface hingga sekitar 6 mm. Cacat yang lebih dalam membutuhkan metode lain seperti UT atau RT karena flux leakage dari cacat dalam tidak cukup kuat mencapai permukaan.', 'Prinsip MT', 'easy'),
  ('Berapa konversi antara Tesla (T) dan Gauss (G) untuk satuan medan magnet?',
   '["1 T = 100 G","1 T = 1000 G","1 T = 10000 G","1 T = 1000000 G"]', 2,
   '1 Tesla setara dengan 10000 Gauss. Konversi ini penting karena gaussmeter lapangan umumnya membaca dalam Gauss sementara spesifikasi teknis kadang dinyatakan dalam Tesla.', 'Fisika MT', 'medium'),
  ('Bagaimana mekanisme terbentuknya flux leakage pada cacat permukaan?',
   '["Partikel besi memanaskan material di lokasi cacat","Saat material dimagnetisasi, diskontinuitas memaksa flux keluar dari permukaan di lokasi cacat","Cacat menyerap medan magnet sepenuhnya","Arus listrik mengalir langsung melalui cacat"]', 1,
   'Ketika material ferromagnetik dimagnetisasi dan terdapat diskontinuitas, garis flux tidak bisa melewati celah cacat sehingga ''bocor'' keluar dari permukaan. Kebocoran flux inilah yang menarik partikel besi membentuk indikasi.', 'Fisika MT', 'easy'),
  ('Orientasi cacat manakah yang memberikan deteksi flux leakage paling kuat?',
   '["Cacat paralel terhadap flux line","Cacat tegak lurus terhadap flux line","Cacat membentuk sudut 10° terhadap flux line","Orientasi cacat tidak berpengaruh"]', 1,
   'Cacat yang tegak lurus terhadap flux line memberikan flux leakage maksimum dan paling kuat terdeteksi. Cacat yang paralel terhadap flux praktis tidak terdeteksi karena flux mengalir mengelilinginya tanpa bocor keluar.', 'Fisika MT', 'easy'),
  ('Pada curve hysteresis, apa yang dimaksud dengan residual magnetism (Br)?',
   '["Medan magnet maksimum yang bisa dicapai material","Sisa magnetisasi (B) saat gaya magnetisasi (H) dikembalikan ke nol","Gaya yang dibutuhkan untuk memagnetisasi material","Suhu di mana material kehilangan sifat magnet"]', 1,
   'Residual magnetism (Br) adalah sisa kerapatan flux (B) yang tertinggal di material saat gaya magnetisasi (H) dikembalikan ke nol. Pada curve hysteresis, B tidak kembali ke nol meskipun H sudah nol.', 'Fisika MT', 'medium'),
  ('Apa yang dimaksud dengan coercive force pada material ferromagnetik?',
   '["Gaya H yang dibutuhkan untuk mengurangi B kembali ke nol","Medan magnet saturasi material","Kemampuan material menarik partikel","Suhu Curie material"]', 0,
   'Coercive force adalah gaya magnetisasi (H) yang dibutuhkan untuk mengurangi kerapatan flux (B) kembali ke nol. Nilai ini menjadi kunci dalam proses demagnetisasi karena menentukan seberapa sulit residual magnetism dihilangkan.', 'Fisika MT', 'hard'),
  ('Material dengan high retentivity paling cocok diinspeksi dengan teknik apa?',
   '["Continuous technique dengan arus selalu ON","Residual technique","Hanya dengan dry powder","Hanya pada suhu tinggi"]', 1,
   'Material dengan high retentivity menyimpan residual magnetism cukup kuat sehingga dapat memakai residual technique — partikel diaplikasikan setelah arus dimatikan. Material low retentivity membutuhkan continuous technique dengan arus ON saat inspeksi.', 'Fisika MT', 'hard'),
  ('Apa keunggulan utama yoke sebagai alat magnetisasi di lapangan?',
   '["Menghasilkan circular field yang sangat kuat","Portable dan praktis untuk inspeksi spot pada las","Dapat menginspeksi cacat sangat dalam","Tidak memerlukan listrik sama sekali"]', 1,
   'Yoke berbentuk U sangat populer di lapangan karena portable dan praktis untuk inspeksi spot pada las dan komponen kecil-medium. Yoke menghasilkan longitudinal field di antara kedua kakinya, bukan circular field.', 'Magnetisasi', 'easy'),
  ('Berapa lifting power minimum untuk AC yoke yang harus diverifikasi sebelum shift?',
   '["18 kg (40 lb)","4.5 kg (10 lb)","10 kg (22 lb)","2 kg (4.4 lb)"]', 1,
   'AC yoke harus memiliki lifting power minimum 4.5 kg (10 lb), diverifikasi sebelum setiap shift. DC yoke memiliki syarat lebih tinggi yaitu minimum 18 kg (40 lb).', 'Magnetisasi', 'medium'),
  ('Berapa lifting power minimum untuk DC yoke?',
   '["4.5 kg (10 lb)","18 kg (40 lb)","9 kg (20 lb)","45 kg (100 lb)"]', 1,
   'DC yoke harus memiliki lifting power minimum 18 kg (40 lb), lebih tinggi dari AC yoke (4.5 kg). Verifikasi lifting power dilakukan sebelum setiap shift.', 'Magnetisasi', 'medium'),
  ('Apa risiko utama penggunaan prod dalam magnetisasi MT?',
   '["Demagnetisasi yang terlalu cepat","Arc strike — bekas terbakar akibat electrical arc","Field yang terlalu lemah","Korosi pada permukaan"]', 1,
   'Risiko utama prod adalah arc strike, yaitu bekas terbakar pada material akibat electrical arc. Untuk mencegahnya, gunakan tip bersih, arus tidak terlalu tinggi, dan tekanan kontak yang baik. Karena risiko ini, prod tidak boleh dipakai untuk material aerospace.', 'Magnetisasi', 'medium'),
  ('Menurut 5-step rule pada coil, sampai jarak berapa komponen efektif diinspeksi dari pusat coil?',
   '["5× diameter coil","5× radius coil","5× panjang komponen","5 cm dari coil"]', 1,
   'Menurut 5-step rule, komponen efektif diinspeksi sampai jarak 5× radius coil dari pusat. Di luar jarak tersebut, field longitudinal menjadi terlalu lemah untuk membentuk indikasi yang andal.', 'Magnetisasi', 'hard'),
  ('Mengapa inspeksi MT selalu harus dilakukan dalam DUA arah magnetisasi yang saling tegak lurus?',
   '["Untuk mempercepat inspeksi","Agar setiap orientasi cacat dapat tertangkap karena cacat hanya terdeteksi bila tegak lurus terhadap flux","Untuk menghemat partikel","Agar residual magnetism lebih kecil"]', 1,
   'Cacat hanya terdeteksi dengan baik bila orientasinya tegak lurus terhadap flux line. Karena cacat bisa berorientasi ke segala arah, inspeksi dilakukan dalam dua arah magnetisasi yang saling tegak lurus untuk menangkap semua orientasi.', 'Magnetisasi', 'easy'),
  ('Circular field (dihasilkan head shot atau prod) paling efektif mendeteksi cacat dengan orientasi apa?',
   '["Cacat transversal (melingkar terhadap sumbu)","Cacat longitudinal (sepanjang sumbu komponen)","Cacat pada sudut 0° terhadap sumbu saja","Cacat internal volumetric"]', 1,
   'Circular field mengalir melingkar di sekitar komponen sehingga mendeteksi cacat longitudinal (sepanjang sumbu). Sebaliknya, longitudinal field (yoke/coil) mendeteksi cacat transversal. Inilah dasar mengapa kedua arah diperlukan.', 'Magnetisasi', 'medium'),
  ('Pada suhu tinggi hingga sekitar 315°C, teknik partikel mana yang paling cocok digunakan?',
   '["Wet fluorescent","Wet visible","Dry powder","Tidak ada teknik MT yang cocok"]', 2,
   'Dry powder cocok untuk suhu tinggi (sampai sekitar 315°C dengan partikel khusus) karena tidak menggunakan carrier cair yang akan menguap. Dry technique juga cocok untuk permukaan kasar dan inspeksi lapangan.', 'Particle & Carrier', 'easy'),
  ('Teknik partikel mana yang memberikan sensitivitas tertinggi untuk crack halus?',
   '["Dry visible","Wet fluorescent","Dry powder pada suhu tinggi","Prod dengan dry powder"]', 1,
   'Wet fluorescent adalah teknik partikel paling sensitif, mampu mendeteksi crack selebar di bawah 1 mikron. Partikel berfluoresensi di bawah UV-A memberikan kontras tinggi, tetapi membutuhkan booth gelap.', 'Particle & Carrier', 'easy'),
  ('Berapa intensitas UV-A minimum pada permukaan inspeksi untuk MT fluorescent?',
   '["100 µW/cm²","500 µW/cm²","1000 µW/cm²","5000 µW/cm²"]', 2,
   'MT fluorescent membutuhkan UV-A minimum 1000 µW/cm² pada permukaan inspeksi, diverifikasi dengan UV meter. Selain itu, ambient white light harus ≤20 lux dalam booth gelap.', 'Particle & Carrier', 'easy'),
  ('Berapa intensitas cahaya putih minimum untuk inspeksi dengan partikel visible?',
   '["100 lux","500 lux","1000 lux","2000 lux"]', 2,
   'Inspeksi dengan partikel visible (warna kontras seperti red, black, gray) membutuhkan cahaya putih minimum 1000 lux pada permukaan inspeksi, diverifikasi dengan lux meter.', 'Particle & Carrier', 'easy'),
  ('Carrier oil untuk wet MT harus memiliki flash point berapa untuk keamanan?',
   '["Lebih dari 38°C","Lebih dari 60°C","Lebih dari 93°C","Lebih dari 200°C"]', 2,
   'Carrier oil (petroleum distillate) harus memiliki flash point lebih dari 93°C untuk mengurangi risiko kebakaran. Oil carrier tidak korosif dan lebih sensitif, tetapi lebih mahal dan memiliki risiko flammable dibanding water carrier.', 'Particle & Carrier', 'hard'),
  ('Pada settling test, berapa volume sediment yang benar untuk wet fluorescent (per 100 mL bath)?',
   '["1.2-2.4 mL","0.1-0.4 mL","5-10 mL","0.5-1.0 mL"]', 1,
   'Untuk wet fluorescent, volume sediment pada settling test adalah 0.1-0.4 mL per 100 mL bath. Untuk visible lebih tinggi yaitu 1.2-2.4 mL. Test dilakukan dengan mendiamkan bath dalam centrifuge tube selama 30 menit.', 'Particle & Carrier', 'hard'),
  ('Mengapa settling test perlu dilakukan secara rutin pada wet bath MT?',
   '["Untuk mengukur suhu carrier","Untuk memverifikasi konsentrasi partikel sesuai spec","Untuk membersihkan tangki","Untuk menghitung lifting power"]', 1,
   'Settling test memverifikasi konsentrasi partikel dalam carrier sesuai spec. Jika terlalu encer sensitivitas turun; jika terlalu pekat dapat menimbulkan false indication. Dilakukan awal shift atau setiap 8 jam dan dicatat di logbook.', 'Particle & Carrier', 'medium'),
  ('Kontaminan apa saja yang harus dihilangkan dari permukaan sebelum inspeksi MT?',
   '["Hanya cat saja","Oil, grease, paint tebal, rust, scale, dan dirt","Hanya partikel besi sisa","Tidak perlu pembersihan apa pun"]', 1,
   'Oil, grease, paint tebal (>50 µm), rust, scale, dan dirt harus dihilangkan karena menutupi atau menahan partikel sehingga indikasi tidak terbentuk dengan baik. Pembersihan dapat dilakukan dengan solvent wipe, vapor degrease, atau wire brush.', 'Surface & Lighting', 'medium'),
  ('Menurut ASME V Article 7, ketebalan coating maksimum yang umumnya diizinkan untuk MT (jika sudah didemonstrasikan)?',
   '["10 µm (0.4 mil)","50 µm (2 mil)","200 µm (8 mil)","500 µm (20 mil)"]', 1,
   'Per ASME V Article 7, coating hingga 50 µm (2 mil) umumnya diizinkan asalkan telah didemonstrasikan tidak menutupi indikasi. Demonstrasi dilakukan dengan test pada specimen identik dengan dan tanpa coating.', 'Surface & Lighting', 'medium'),
  ('Berapa ambient white light maksimum yang diizinkan dalam booth fluorescent MT?',
   '["≤ 20 lux","≤ 100 lux","≤ 500 lux","≤ 1000 lux"]', 0,
   'Dalam booth fluorescent, ambient white light harus ≤20 lux agar fluoresensi partikel terlihat jelas. Selain itu UV-A harus ≥1000 µW/cm² pada permukaan inspeksi.', 'Surface & Lighting', 'medium'),
  ('Berapa lama inspector harus melakukan adaptasi mata sebelum inspeksi fluorescent di booth gelap?',
   '["10 detik","1 menit","15 menit","30 menit"]', 1,
   'Inspector wajib melakukan adaptasi mata selama 1 menit di booth gelap sebelum inspeksi fluorescent agar mata dapat melihat indikasi dengan baik. UV blocking glasses juga digunakan untuk keselamatan.', 'Surface & Lighting', 'easy'),
  ('Bagaimana cara membedakan indikasi linear dari round?',
   '["Linear berwarna merah, round berwarna hitam","Linear: panjang ≥ 3× lebar; round: panjang < 3× lebar","Linear selalu lebih besar dari round","Linear hanya di las, round hanya di casting"]', 1,
   'Indikasi diklasifikasikan linear jika panjangnya ≥ 3× lebar, dan round jika panjangnya < 3× lebar. Klasifikasi ini penting karena acceptance criteria berbeda untuk linear dan round.', 'Indikasi', 'easy'),
  ('Karakteristik indikasi apa yang khas untuk crack?',
   '["Round, scattered, dan multiple kecil","Linear, sharp, sering branched dengan akumulasi partikel padat","Selalu berbentuk lingkaran sempurna","Indikasi yang loose dan mudah hilang"]', 1,
   'Crack memberikan indikasi linear, sharp (tajam), sering branched (bercabang), dengan akumulasi partikel yang padat. Sebaliknya, porosity memberikan indikasi round dan scattered.', 'Indikasi', 'easy'),
  ('Apa yang dimaksud dengan ''magnetic writing'' sebagai false indication?',
   '["Tulisan yang dibuat inspector pada laporan","Partikel terkumpul di lokasi yang pernah disentuh material magnetik lain","Cacat asli berbentuk huruf","Indikasi porosity yang berderet"]', 1,
   'Magnetic writing adalah false indication di mana partikel terkumpul di lokasi yang pernah bersentuhan dengan material magnetik lain (misalnya yoke atau palu). Indikasi ini hilang setelah demag dan re-test, sedangkan indikasi cacat asli akan muncul lagi.', 'Indikasi', 'medium'),
  ('Bagaimana cara memverifikasi apakah suatu indikasi adalah cacat asli?',
   '["Mengabaikannya jika kecil","Bersihkan permukaan, re-magnetize, dan re-apply particles — indikasi asli muncul lagi di lokasi yang sama","Menambah arus magnetisasi hingga indikasi hilang","Hanya berdasarkan warna partikel"]', 1,
   'Verifikasi dilakukan dengan membersihkan permukaan, re-magnetize, dan re-apply particles. Indikasi cacat asli akan muncul kembali di lokasi yang sama, sedangkan false indication seperti magnetic writing tidak. Konfirmasi tambahan dapat memakai PT atau magnifier 10×.', 'Indikasi', 'medium'),
  ('Lack of fusion pada inspeksi las MT umumnya memberikan indikasi seperti apa dan di mana?',
   '["Round dan scattered di tengah pelat","Linear di area las, lokasi tipikal weld toe atau sidewall","Hanya terlihat sebagai porosity","Tidak pernah terdeteksi oleh MT"]', 1,
   'Lack of fusion memberikan indikasi linear di area las, dengan lokasi tipikal di weld toe atau sidewall. Karena bersifat linear dan terbuka ke permukaan atau near-surface, indikasi ini terdeteksi oleh MT.', 'Indikasi', 'hard'),
  ('Mengapa residual magnetism perlu dihilangkan (demagnetisasi) setelah inspeksi MT?',
   '["Agar partikel lebih mudah dibersihkan","Karena mengganggu welding, menarik chip ke moving parts, dan menimbulkan interferensi instrumen","Agar komponen lebih ringan","Untuk menambah kekuatan material"]', 1,
   'Residual magnetism perlu dihilangkan karena dapat mengganggu welding (arc deflection), menarik chip metal ke moving parts (bearing, gear), dan menyebabkan interferensi dengan instrumen di sekitar. Demag bukan untuk mempermudah pembersihan partikel.', 'Demagnetisasi', 'easy'),
  ('Menurut ASTM E709, berapa batas residual magnetism untuk komponen umum?',
   '["≤ 3 G","≤ 20 G","≤ 50 G","≤ 100 G"]', 0,
   'Per ASTM E709, residual magnetism untuk komponen umum dibatasi ≤ 3 G, sedangkan komponen aerospace lebih ketat yaitu ≤ 2 G. Verifikasi dilakukan dengan field indicator (gaussmeter) pada beberapa titik komponen.', 'Demagnetisasi', 'medium'),
  ('Teknik demagnetisasi apa yang paling efektif untuk material thin dan medium?',
   '["Heating above Curie temperature","AC decay — amplitudo AC field diturunkan gradual ke nol","Menambah arus DC maksimum","Mengubah orientasi komponen"]', 1,
   'AC decay, di mana komponen ditaruh dalam AC field yang amplitudonya diturunkan gradual ke nol, paling efektif untuk material thin dan medium. Untuk material tebal yang AC tidak penetrasi dengan baik, digunakan reverse DC.', 'Demagnetisasi', 'medium'),
  ('Teknik demag mana yang paling cocok untuk komponen panjang?',
   '["Walking through — komponen ditarik perlahan keluar dari coil AC","Heating above Curie temperature","Single shot DC","Hanya mengandalkan AC decay tanpa pergerakan"]', 0,
   'Walking through, yaitu komponen dilewatkan melalui coil AC sambil ditarik perlahan menjauh, cocok untuk komponen panjang. Heating above Curie (~770°C untuk baja) bersifat ekstrim dan jarang dipakai.', 'Demagnetisasi', 'hard'),
  ('Code utama yang mengatur MT pada pressure equipment adalah?',
   '["ASME V Article 6","ASME V Article 7","ASME V Article 2","AWS D1.1 saja"]', 1,
   'ASME V Article 7 adalah code utama untuk MT pada pressure equipment, mengatur magnetisasi, lighting, particles, dan acceptance criteria. ASME V Article 6 untuk PT dan Article 2 untuk RT.', 'Code & Procedures', 'medium'),
  ('Pada inspeksi yoke continuous technique, kapan partikel diaplikasikan?',
   '["Setelah arus magnetisasi dimatikan","Selama magnetisasi berlangsung (arus ON)","Sebelum pembersihan permukaan","Setelah demagnetisasi"]', 1,
   'Pada continuous technique, partikel diaplikasikan selama magnetisasi berlangsung (arus ON). Ini berbeda dengan residual technique di mana partikel diaplikasikan setelah arus dimatikan, yang hanya cocok untuk material high-retentivity.', 'Field Practice', 'medium'),
  ('Apa urutan langkah yang benar saat inspeksi weld dua arah dengan yoke?',
   '["Magnetize → demag → clean → inspect","Clean → magnetize arah 1 → apply particles → inspect → demag → magnetize arah 2 → ulangi","Apply particles → magnetize → clean → inspect","Inspect → clean → magnetize → demag"]', 1,
   'Urutan yang benar: clean permukaan, magnetize arah pertama, apply particles, inspect dan tandai indikasi, demag, lalu magnetize arah kedua (tegak lurus) dan ulangi. Demag di antara dua arah mencegah magnetic writing.', 'Field Practice', 'hard'),
  ('Informasi temuan apa yang wajib dicantumkan dalam MT report?',
   '["Hanya nama inspector","Lokasi indikasi, tipe (linear/round), panjang, dan klasifikasi accept/reject","Hanya jumlah total indikasi","Hanya foto tanpa keterangan"]', 1,
   'Bagian findings dalam MT report harus mencakup lokasi indikasi, tipe (linear/round), panjang, dan klasifikasi (accept/reject) sesuai applicable code. Report juga memuat header, equipment & kalibrasi, detail magnetisasi, dan sign-off inspector.', 'Reporting', 'easy')
) AS q(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L1' AND m."orderIndex" = 12 AND ls."orderIndex" = 2 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ============================================
-- PT-L1 FINAL ASSESSMENT (module 12, step 2) — 40 questions
-- ============================================
-- Idempotent: clear any previously-seeded questions for this final-assessment step first.
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L1' AND m."orderIndex" = 12 AND ls."orderIndex" = 2 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, q.question, q.options::jsonb, q."correctAnswer", q.explanation, q.category, 'PT', 'Level I', q.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa prinsip fisika utama yang memungkinkan penetran masuk ke dalam celah retak permukaan pada metode Liquid Penetrant Testing (PT)?',
   '["Induksi elektromagnetik","Aksi kapiler (capillary action)","Kebocoran fluks magnet","Atenuasi radiasi"]', 1,
   'PT bekerja berdasarkan aksi kapiler, di mana cairan ber-viskositas rendah dan wetting baik meresap ke celah halus. Induksi elektromagnetik (ET), kebocoran fluks magnet (MT), dan atenuasi radiasi (RT) adalah prinsip metode NDT lain.', 'physics', 'easy'),
  ('Jenis cacat apa yang dapat dideteksi oleh metode PT?',
   '["Cacat internal di tengah material","Hanya cacat pada material ferromagnetik","Variasi ketebalan dinding pipa","Cacat yang terbuka ke permukaan (surface-breaking)"]', 3,
   'PT hanya mendeteksi cacat yang terbuka ke permukaan karena penetran harus dapat masuk ke celah dari permukaan. Cacat internal butuh RT/UT, dan PT tidak terbatas pada material ferromagnetik (itu MT).', 'principles', 'easy'),
  ('Manakah keunggulan utama metode PT untuk inspeksi lapangan?',
   '["Murah, cepat, dan portable","Dapat mengukur kedalaman cacat secara presisi","Tidak memerlukan persiapan permukaan","Dapat mendeteksi cacat internal"]', 0,
   'PT unggul karena murah, cepat, dan portable sehingga cocok untuk inspeksi lapangan dan pre-weld. PT tidak mengukur kedalaman cacat, tetap butuh permukaan bersih, dan tidak mendeteksi cacat internal.', 'principles', 'easy'),
  ('Mengapa PT dapat dipakai pada material non-ferromagnetik seperti aluminum, stainless steel austenitic, dan keramik, sedangkan MT tidak bisa?',
   '["PT memakai partikel magnetik yang lebih halus","PT memakai radiasi yang menembus semua material","PT tidak bergantung pada sifat magnetik material, hanya pada permukaan non-porous","PT hanya bekerja pada material konduktif"]', 2,
   'PT bekerja lewat aksi kapiler pada permukaan non-porous apa pun tanpa memerlukan sifat ferromagnetik. MT membutuhkan material yang dapat dimagnetisasi sehingga tidak cocok untuk aluminum atau austenitic stainless.', 'principles', 'easy'),
  ('Apa perbedaan utama antara Penetrant Type I dan Type II?',
   '["Type I water washable, Type II solvent removable","Type I untuk logam, Type II untuk plastik","Type I berwarna merah, Type II hijau","Type I fluorescent (dilihat di UV-A), Type II visible (dilihat di cahaya putih)"]', 3,
   'Type I adalah penetran fluorescent yang berfluoresensi di bawah UV-A dengan sensitivitas tertinggi, sedangkan Type II adalah penetran visible (umumnya merah) yang dilihat di cahaya putih. Pembagian removal (Method A/B/C/D) adalah klasifikasi terpisah dari Type.', 'equipment', 'easy'),
  ('Untuk inspeksi komponen kritis seperti turbine blade aerospace dengan crack sangat halus, jenis penetran apa yang paling sesuai?',
   '["Type II visible karena lebih praktis","Type I fluorescent karena sensitivitas tertinggi","Penetran apa pun memberi hasil sama","Type II karena tidak butuh booth gelap"]', 1,
   'Type I fluorescent memiliki sensitivitas tertinggi sehingga paling cocok untuk crack halus dan komponen kritis seperti aerospace dan nuclear. Type II memiliki sensitivitas lebih rendah dan dipakai untuk inspeksi cepat lapangan.', 'equipment', 'easy'),
  ('Berapa penetrant dwell time minimum yang ditetapkan ASME V Article 6 untuk crack normal?',
   '["1 menit","5 menit","30 menit","60 menit"]', 1,
   'ASME V Article 6 menetapkan minimum 5 menit untuk crack normal, sedangkan ASTM E165 menetapkan 10 menit sebagai standar industri umum. Crack sangat halus dapat membutuhkan dwell sampai 30 menit.', 'technique', 'easy'),
  ('Mengapa langkah excess removal disebut langkah paling kritis dalam PT?',
   '["Karena memakan waktu paling lama","Karena jika salah dapat menimbulkan false indication atau malah mengeluarkan penetran dari crack","Karena memerlukan alat paling mahal","Karena harus dilakukan dua kali"]', 1,
   'Excess removal yang berlebihan dapat menarik penetran keluar dari crack (indikasi hilang), sedangkan yang kurang menyebabkan background dan false indication. Inilah langkah yang paling sering membuat trainee Level I gagal.', 'technique', 'easy'),
  ('Manakah pernyataan yang benar tentang aturan dasar excess removal?',
   '["Hapus penetran dari permukaan, BUKAN dari celah cacat","Hapus penetran dari celah cacat sebanyak mungkin","Wipe sekuat dan seagresif mungkin","Selalu gunakan air panas untuk mempercepat"]', 0,
   'Aturan dasarnya adalah menghapus penetran dari permukaan saja dan tidak dari celah cacat. Wipe harus seminimal dan selembut mungkin agar penetran di dalam crack tetap utuh untuk membentuk indikasi.', 'technique', 'easy'),
  ('Berapa intensitas cahaya putih minimum yang disyaratkan pada permukaan untuk inspeksi PT visible (Type II)?',
   '["100 lux","500 lux","2000 lux","1000 lux"]', 3,
   'Inspeksi visible PT mensyaratkan minimum 1000 lux pada permukaan, diverifikasi dengan lux meter setiap awal shift. Intensitas yang kurang dapat menyebabkan indikasi terlewat.', 'calibration', 'easy'),
  ('Bagaimana sebuah indikasi diklasifikasikan sebagai LINEAR?',
   '["Panjang kurang dari 3x lebar","Panjang sama dengan lebar","Berbentuk lingkaran sempurna","Panjang lebih besar atau sama dengan 3x lebar"]', 3,
   'Indikasi linear memiliki panjang >= 3x lebarnya dan biasanya menandakan crack, lack of fusion, atau lap. Indikasi round (panjang <3x lebar) umumnya menandakan porosity yang relatif kurang kritis.', 'interpretation', 'easy'),
  ('Indikasi berbentuk bulat dengan panjang kurang dari 3x lebar (round indication) paling mungkin disebabkan oleh apa?',
   '["Porosity atau gas pocket","Crack","Lack of fusion","Lap memanjang"]', 0,
   'Round indication (panjang <3x lebar) umumnya menunjukkan porosity, gas pocket, atau foreign material yang umumnya kurang severe dibanding indikasi linear. Crack, lack of fusion, dan lap menghasilkan indikasi linear.', 'interpretation', 'easy'),
  ('Mengapa batch number setiap chemical (penetran, developer, emulsifier) harus dicatat di logbook setiap inspeksi?',
   '["Untuk traceability dan dokumentasi mutu inspeksi","Untuk menghitung pajak","Karena chemical akan kadaluarsa esok hari","Agar bisa dikembalikan ke supplier"]', 0,
   'Pencatatan batch number memberikan traceability dan bukti dokumentasi mutu, sehingga jika ada masalah hasil dapat ditelusuri ke material yang dipakai. Ini bagian dari kontrol kualitas inspeksi.', 'standards', 'easy'),
  ('Pada akhir proses PT, mengapa dilakukan post-cleaning?',
   '["Untuk membentuk indikasi baru","Untuk menambah sensitivitas","Untuk menghilangkan sisa penetran/developer yang dapat menyebabkan korosi atau mengganggu proses selanjutnya","Untuk memverifikasi crack"]', 2,
   'Post-cleaning menghilangkan sisa penetran dan developer yang dapat menyebabkan korosi atau mengganggu proses berikutnya seperti pengelasan atau pengecatan. Ini langkah penutup standar dalam sequence PT.', 'technique', 'easy'),
  ('Berapa jarak pandang (viewing distance) yang dianjurkan dari permukaan saat melakukan inspeksi PT?',
   '["5-10 cm","1-2 meter","30-60 cm","Lebih dari 2 meter"]', 2,
   'Jarak pandang yang dianjurkan adalah 30-60 cm dari permukaan, dengan memvariasikan sudut untuk menangkap indikasi yang reflective. Untuk crack halus dapat digunakan hand magnifier 3-10x.', 'technique', 'easy'),
  ('Mengapa coating atau cat harus dihilangkan dari permukaan sebelum PT dilakukan?',
   '["Karena coating dapat menutupi mulut crack sehingga penetran tidak bisa masuk","Agar penetran tidak luntur","Karena coating membuat developer terlalu tebal","Karena coating selalu berfluoresensi"]', 0,
   'Coating atau cat dapat menutupi/menjembatani mulut crack sehingga penetran tidak dapat masuk dan cacat terlewat. Permukaan harus bebas coating dan kontaminan agar PT efektif.', 'technique', 'easy'),
  ('Tegangan permukaan penetran sengaja didesain lebih rendah dibanding air. Kira-kira berapa nilai tegangan permukaan air dan penetran tipikal?',
   '["Air ~30 mN/m, penetran ~72 mN/m","Keduanya ~50 mN/m","Air ~10 mN/m, penetran ~100 mN/m","Air ~72 mN/m, penetran ~30 mN/m"]', 3,
   'Air memiliki tegangan permukaan ~72 mN/m sedangkan penetran didesain rendah ~30 mN/m agar lebih mudah masuk celah halus. Tegangan permukaan yang lebih rendah meningkatkan kemampuan penetrasi.', 'physics', 'medium'),
  ('Pada nilai sudut kontak (contact angle) berapa cairan dikatakan memiliki wetting yang baik sehingga menyebar di permukaan?',
   '["Kurang dari 90°","Lebih besar dari 90°","Tepat 180°","Tepat 90°"]', 0,
   'Wetting yang baik terjadi saat sudut kontak <90°, di mana cairan menyebar dan masuk celah. Sudut >90° menyebabkan cairan menggumpal dan tidak masuk celah cacat.', 'physics', 'medium'),
  ('Pada animasi PT, indikasi yang terbentuk setelah developer bekerja umumnya tampak jauh lebih lebar dari retak aslinya. Apa penyebabnya?',
   '["Developer melebarkan retak secara fisik","Developer menarik penetran keluar dan menyebarkannya (bleed-out) sehingga indikasi membesar dan mudah dilihat","Penetran memuai akibat panas inspeksi","Cahaya UV membesarkan bayangan retak"]', 1,
   'Developer menarik penetran keluar dari celah lewat reverse capillary action lalu menyebarkannya sebagai bleed-out, sehingga indikasi tampak jauh lebih lebar dari retak asli dan mudah dilihat mata. Developer tidak melebarkan retak secara fisik.', 'physics', 'medium'),
  ('Menurut ASME V Article 6, berapa rentang temperatur standar (window) untuk pelaksanaan PT tanpa perlu kualifikasi prosedur tambahan?',
   '["10-52°C (50-125°F)","0-100°C","20-30°C saja","52-80°C"]', 0,
   'ASME V Article 6 menetapkan window temperatur 10-52°C (50-125°F). Di luar rentang ini diperlukan kualifikasi prosedur karena penetran dapat menguap terlalu cepat (panas) atau viskositasnya naik (dingin).', 'calibration', 'medium'),
  ('Apa dampak utama temperatur tinggi (di atas 52°C) terhadap penetran selama dwell?',
   '["Viskositas naik sehingga penetran lebih tahan","Penetran cepat menguap/mengering sehingga indikasi tidak terbentuk baik","Penetran berubah warna menjadi tidak kontras","Aksi kapiler menjadi lebih lambat"]', 1,
   'Pada temperatur tinggi viskositas turun drastis dan penetran cepat menguap, sehingga indikasi tidak terbentuk dengan baik. Karena itu ASME V membatasi maksimum 52°C.', 'physics', 'medium'),
  ('Pada Method A (water washable), bagaimana excess penetran dihilangkan?',
   '["Dengan air karena penetran sudah mengandung emulsifier","Dengan solvent dan lap","Dengan emulsifier yang diaplikasikan terpisah setelah dwell","Dengan menyeka kering saja"]', 0,
   'Method A adalah water washable di mana penetran sudah mengandung emulsifier, sehingga excess dapat langsung dibilas dengan air. Method ini cepat tetapi sensitivitasnya lebih rendah dibanding post-emulsifiable.', 'equipment', 'medium'),
  ('Sensitivity level penetran fluorescent dikelompokkan dari 1 sampai 4. Level mana yang paling sering dipakai untuk inspeksi industri umum dan weld?',
   '["Level 1 (Ultra-low)","Level 3 (High)","Level 4 (Ultra-high)","Level 2 (Medium)"]', 3,
   'Level 2 (Medium) adalah sensitivitas yang paling sering dipakai untuk industri umum dan weld inspection. Level 1 untuk crack halus, sedangkan Level 4 untuk aplikasi kritis aerospace yang sangat ketat dan mahal.', 'equipment', 'medium'),
  ('Pada teknik water wash, manakah kombinasi tekanan, temperatur air, sudut, dan jarak nozzle yang benar agar indikasi tidak ter-wash?',
   '["Maks 40 psi, 10-38°C, sudut 45°, jarak nozzle min 30 cm","Maks 100 psi, 50-70°C, sudut 90°, jarak 5 cm","Maks 150 psi, air panas, sudut 0°, jarak 10 cm","Tanpa batas tekanan, air dingin, sudut bebas, jarak bebas"]', 0,
   'Water wash dibatasi tekanan maks 40 psi (276 kPa), temperatur 10-38°C, sudut semprot 45°, dan jarak nozzle minimal 30 cm agar excess hilang tanpa mencuci penetran keluar dari indikasi. Tekanan tinggi, air panas, sudut tegak lurus, atau jarak terlalu dekat berisiko over-wash.', 'technique', 'medium'),
  ('Developer Form apa yang paling sensitif dan umum dipakai untuk visible PT karena memberikan latar putih kontras?',
   '["Form a — Dry powder","Form c — Wet non-aqueous (solvent based)","Form b — Wet aqueous","Form d — Water-soluble"]', 1,
   'Form c (wet non-aqueous) menggunakan powder dalam solvent dan diaplikasikan dengan spray, memberikan lapisan putih kontras paling sensitif untuk visible PT. Form a cocok untuk fluorescent, sedangkan Form b/d kurang sensitif.', 'equipment', 'medium'),
  ('Menurut ASME V, berapa developer dwell time minimum sebelum interpretasi dilakukan?',
   '["1 menit","7 menit","20 menit","60 menit"]', 1,
   'Developer dwell minimum adalah 7 menit per ASME V, dengan maksimum sekitar 30 menit. Waktu ini memberi kesempatan bleed-out terbentuk; crack besar muncul cepat sedangkan crack halus butuh lebih lama.', 'technique', 'medium'),
  ('Untuk inspeksi PT fluorescent (Type I), berapa intensitas UV-A minimum dan batas cahaya putih ambient yang disyaratkan?',
   '["UV-A 100 µW/cm² min, ambient white light 1000 lux","UV-A 500 µW/cm² min, tanpa batas ambient","UV-A 1000 µW/cm² min, ambient white light <20 lux","UV-A 2000 µW/cm² min, ambient white light <100 lux"]', 2,
   'Fluorescent PT mensyaratkan UV-A minimum 1000 µW/cm² pada permukaan dan cahaya putih ambient di bawah 20 lux (booth gelap). Ini memastikan kontras fluoresensi indikasi terlihat jelas.', 'calibration', 'medium'),
  ('Saat menginspeksi PT fluorescent, mengapa kacamata pelindung UV (UV-blocking glasses) digunakan?',
   '["Untuk meningkatkan kontras indikasi","Untuk keselamatan, melindungi mata dari paparan UV-A","Untuk membuat penetran lebih terang","Untuk menggantikan booth gelap"]', 1,
   'UV-blocking glasses dipakai untuk melindungi mata inspektor dari paparan radiasi UV-A selama inspeksi fluorescent. Ini aspek keselamatan, bukan untuk meningkatkan kontras.', 'safety', 'medium'),
  ('Sebelum aplikasi penetran, mengapa air yang terperangkap di dalam crack harus dihilangkan sempurna (low temperature drying)?',
   '["Agar developer tidak menggumpal","Karena air dalam celah memblok masuknya penetran","Agar penetran tidak berubah warna","Karena air merusak emulsifier"]', 1,
   'Air yang terperangkap di dalam crack akan memblok celah sehingga penetran tidak dapat masuk dan cacat terlewat. Permukaan dan celah harus benar-benar bersih dan kering sebelum penetran diaplikasikan.', 'technique', 'medium'),
  ('Seorang inspektor menemukan indikasi yang setelah re-clean dan re-test tidak muncul kembali di lokasi yang sama. Indikasi semula kemungkinan besar adalah?',
   '["Crack asli yang dalam","False/process indication (mis. dari scratch, lap, atau penetran terjebak di ridge)","Lack of fusion","Indikasi yang harus langsung di-reject"]', 1,
   'Indikasi yang hilang setelah re-clean dan re-test menandakan false/process indication, misalnya penetran terjebak di scratch, lap, atau ridge, bukan cacat asli. Cacat asli akan muncul kembali secara konsisten.', 'interpretation', 'medium'),
  ('Code mana yang menjadi acuan utama PT untuk pressure equipment (bejana tekan)?',
   '["ASME V Article 6","AWS D1.1","ASTM E709","ISO 9934"]', 0,
   'ASME V Article 6 adalah code utama PT untuk pressure equipment yang mengatur material, teknik, pencahayaan, dan acceptance. ASTM E709/ISO 9934 adalah standar MT, dan AWS D1.1 adalah welding code struktur baja.', 'standards', 'medium'),
  ('Mengapa penetran, emulsifier, dan developer sebaiknya berasal dari satu manufacturer dan satu ''family'' produk?',
   '["Agar lebih murah saat membeli","Karena mencampur brand/family berbeda dapat membatalkan (cancel) sensitivitas sistem","Agar warnanya seragam saja","Karena diwajibkan oleh peraturan pajak"]', 1,
   'Penetran, emulsifier, dan developer dari family yang sama dirancang kompatibel secara kimia; mencampur brand/family berbeda dapat membatalkan sensitivitas sistem. Manufacturer biasanya menerbitkan compatible family list.', 'standards', 'medium'),
  ('Dalam persamaan tinggi naik kapiler h = (2γcosθ)/(ρgr), apa yang terjadi pada tinggi naik penetran jika jari-jari celah (r) semakin kecil?',
   '["Tinggi naik semakin kecil","Tinggi naik tidak berubah","Penetran tidak bisa naik sama sekali","Tinggi naik semakin besar"]', 3,
   'Karena r berada di penyebut, semakin kecil jari-jari celah maka tinggi naik kapiler (h) semakin besar. Inilah sebabnya penetran sangat efektif masuk ke celah retak yang sangat halus.', 'physics', 'hard'),
  ('Apa perbedaan antara Method B dan Method D dalam hal emulsifier?',
   '["Method B memakai air, Method D memakai solvent","Method B tidak memakai emulsifier, Method D memakai","Method B memakai emulsifier lipophilic (berbasis minyak), Method D hydrophilic (diencerkan air)","Keduanya identik"]', 2,
   'Method B adalah post-emulsifiable lipophilic (emulsifier berbasis minyak), sedangkan Method D adalah post-emulsifiable hydrophilic dengan emulsifier yang diencerkan air sehingga memberi kontrol lebih baik daripada Method B.', 'equipment', 'hard'),
  ('Pada Method B (post-emulsifiable lipophilic), mengapa waktu kontak emulsifier harus dikontrol ketat (time-controlled)?',
   '["Agar emulsifier tidak menguap","Agar emulsifier tidak bereaksi dengan developer","Agar emulsifier tidak masuk ke celah cacat dan mengeluarkan penetran dari sana","Agar warna penetran tidak berubah"]', 2,
   'Emulsifier pada Method B harus time-controlled supaya hanya meng-emulsi penetran di permukaan dan tidak masuk ke celah cacat. Jika emulsifier masuk celah, penetran di dalam cacat ikut terangkat dan indikasi hilang.', 'technique', 'hard'),
  ('Jika selama excess removal dengan solvent wipe permukaan langsung dibasahi solvent (tanpa dry wipe lebih dulu) atau solvent disemprot langsung ke part, apa risikonya?',
   '["Developer akan mengering terlalu cepat","Solvent dapat mendorong/menarik penetran keluar dari crack sehingga indikasi hilang","Penetran berubah menjadi fluorescent","Tidak ada risiko, justru mempercepat proses"]', 1,
   'Membasahi langsung dengan solvent atau menyemprot solvent ke part dapat mendorong dan menarik penetran keluar dari celah crack sehingga indikasi hilang. Teknik benar: dry wipe dulu, lalu lap yang sedikit dibasahi solvent, lalu dry wipe akhir.', 'technique', 'hard'),
  ('Mengapa indikasi linear umumnya dianggap lebih kritis daripada indikasi round pada inspeksi weld?',
   '["Karena lebih mudah dilihat","Karena round selalu false indication","Karena round selalu lebih besar","Karena linear cenderung mewakili crack/lack of fusion yang dapat merambat (propagate)"]', 3,
   'Indikasi linear cenderung mewakili cacat seperti crack atau lack of fusion yang dapat merambat di bawah beban, sehingga lebih kritis. Indikasi round (porosity) umumnya kurang severe karena tidak setajam crack.', 'interpretation', 'hard'),
  ('Jika indikasi menyebar (spread) sangat cepat dan lebar saat developer dwell, kemungkinan penyebabnya adalah?',
   '["Developer terlalu tebal","Crack besar ATAU temperatur komponen terlalu tinggi","Dwell penetran terlalu pendek","Pencahayaan kurang"]', 1,
   'Indikasi yang spread cepat dapat menandakan crack besar atau temperatur yang terlalu tinggi. Jika penyebabnya temperatur, inspeksi harus dihentikan dan ditunggu hingga komponen mendingin ke window yang diizinkan.', 'interpretation', 'hard'),
  ('Sebuah crack halus diduga sangat tight (<1 µm). Penyesuaian apa yang tepat agar penetran dapat masuk?',
   '["Memperpendek dwell time menjadi 1 menit","Memperpanjang dwell time penetran (sampai sekitar 30 menit)","Menaikkan temperatur ke 60°C","Menambah tekanan air saat wash"]', 1,
   'Crack yang sangat tight membutuhkan dwell time penetran yang diperpanjang (sampai sekitar 30 menit) agar aksi kapiler sempat mengisi celah halus. Mempersingkat dwell atau menaikkan temperatur di atas batas justru kontraproduktif.', 'technique', 'hard'),
  ('Pada developer dwell, mengapa reading/interpretasi sebaiknya dilakukan beberapa kali selama periode dwell?',
   '["Untuk menangkap perkembangan indikasi karena crack besar muncul cepat dan crack halus muncul lambat","Agar developer tidak mengering","Karena pencahayaan berubah-ubah","Agar penetran tidak menguap"]', 0,
   'Crack besar memunculkan bleed-out dalam 2 menit sedangkan crack halus baru muncul setelah 10-15 menit, sehingga reading beberapa kali memastikan semua indikasi tertangkap. Reading sekali saja berisiko melewatkan crack halus.', 'interpretation', 'hard')
) AS q(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L1' AND m."orderIndex" = 12 AND ls."orderIndex" = 2 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ============================================
-- RT-L1 FINAL ASSESSMENT (module 14, step 2) — 40 questions
-- ============================================
-- Idempotent: clear any previously-seeded questions for this final-assessment step first.
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L1' AND m."orderIndex" = 14 AND ls."orderIndex" = 2 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, q.question, q.options::jsonb, q."correctAnswer", q.explanation, q.category, 'RT', 'Level I', q.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa prinsip dasar Radiographic Testing (RT)?',
   '["Menyemprotkan partikel besi ke permukaan yang dimagnetisasi","Memakai radiasi pengion (X-ray atau gamma) untuk membuat citra struktur internal material","Mengirim gelombang suara ultrasonik ke dalam material","Meresapkan cairan penetran ke celah retak permukaan"]', 1,
   'RT memakai radiasi pengion X-ray atau gamma yang menembus material; variasi kepadatan internal terekam pada film/detektor. Partikel besi adalah MT, gelombang suara adalah UT, dan penetran adalah PT.', 'Pengantar RT', 'easy'),
  ('Keunggulan utama RT dibanding PT dan MT adalah kemampuannya untuk:',
   '["Hanya mendeteksi cacat permukaan dengan sangat cepat","Diterapkan tanpa peraturan keselamatan apa pun","Bekerja hanya pada material ferromagnetik","Mendeteksi cacat di dalam (volumetrik) seperti porosity dan slag di tengah weld"]', 3,
   'RT adalah metode volumetrik sehingga dapat melihat cacat internal seperti porosity, slag, dan lack of penetration di tengah weld, sedangkan PT/MT hanya mendeteksi cacat permukaan/near-surface.', 'Pengantar RT', 'easy'),
  ('Pada radiograph, area dengan kepadatan material lebih rendah (misalnya void/porosity) akan tampak:',
   '["Lebih terang dari area sekitarnya","Lebih gelap dari area sekitarnya","Sama persis dengan base metal","Berwarna merah cerah"]', 1,
   'Void/porosity meneruskan lebih banyak foton ke film sehingga area itu menjadi lebih gelap (density lebih tinggi). Material yang lebih padat menyerap lebih banyak radiasi sehingga tampak lebih terang.', 'Pengantar RT', 'medium'),
  ('Pada tabung X-ray, parameter yang mengontrol energi (daya tembus) radiasi adalah:',
   '["mA (arus tabung)","kV (tegangan tinggi)","Exposure time","Focal-to-film distance"]', 1,
   'kV (tegangan tinggi) mengatur energi/penetrasi X-ray. mA mengontrol intensitas (jumlah radiasi) dan time menentukan total exposure.', 'Sumber Radiasi', 'easy'),
  ('Sumber gamma Iridium-192 memiliki half-life sekitar:',
   '["5,27 tahun","120 hari","74 hari","30 menit"]', 2,
   'Ir-192 ber-half-life ~74 hari (energi ~380 keV) sehingga source harus diganti tiap ~3 bulan. 5,27 tahun adalah Co-60 dan 120 hari adalah Se-75.', 'Sumber Radiasi', 'medium'),
  ('Sumber gamma yang paling cocok untuk menembus baja sangat tebal (>50 mm) adalah:',
   '["Selenium-75","Iridium-192","Cobalt-60","X-ray 100 kV"]', 2,
   'Co-60 berenergi ~1,25 MeV sehingga mampu menembus baja sangat tebal. Se-75 (~270 keV) dan Ir-192 (~380 keV) lebih cocok untuk baja tipis-menengah, dan X-ray 100 kV jauh terlalu lemah.', 'Sumber Radiasi', 'medium'),
  ('Untuk baja tipis (<=25 mm), sumber gamma yang memberi kontras lebih baik dibanding Ir-192 adalah:',
   '["Selenium-75","Cobalt-60","X-ray 450 kV","Linear accelerator >1 MeV"]', 0,
   'Se-75 (~270 keV, half-life 120 hari) berenergi lebih rendah dari Ir-192 sehingga memberi kontras lebih baik untuk baja tipis. Co-60 dan sumber energi sangat tinggi justru menurunkan kontras pada baja tipis.', 'Sumber Radiasi', 'hard'),
  ('Kepanjangan dan makna prinsip ALARA adalah:',
   '["Always Limit All Radiation Areas — menutup semua area radiasi","As Long As Required Approved — selama disetujui","Annual Limit At Reactor Areas — batas tahunan di reaktor","As Low As Reasonably Achievable — menekan paparan serendah yang praktis"]', 3,
   'ALARA berarti As Low As Reasonably Achievable, yaitu filosofi optimasi untuk menekan paparan serendah yang masih praktis, bukan sekadar memenuhi angka batas.', 'Keselamatan Radiasi', 'easy'),
  ('Tiga pilar utama proteksi radiasi dalam ALARA adalah:',
   '["Time, Distance, Shielding","Energy, Current, Voltage","Film, Screen, Developer","Source, Object, Film"]', 0,
   'Tiga pilar ALARA adalah Time (kurangi durasi paparan), Distance (jauhi sumber), dan Shielding (pakai lapisan penahan). Opsi lain adalah parameter X-ray atau geometri exposure.', 'Keselamatan Radiasi', 'easy'),
  ('Menurut inverse square law, jika jarak ke sumber digandakan menjadi 2 kali, maka dose rate menjadi:',
   '["1/2 dari semula","1/4 dari semula","2 kali semula","Tetap sama"]', 1,
   'Dose rate sebanding dengan 1/r^2, sehingga jarak 2 kali menurunkan dose menjadi 1/4. Inilah mengapa jarak adalah perlindungan paling efektif.', 'Keselamatan Radiasi', 'medium'),
  ('Batas dosis seluruh tubuh tahunan untuk pekerja radiasi (occupational) adalah:',
   '["1 mSv per tahun","5 mSv per tahun","50 mSv per tahun","500 mSv per tahun"]', 2,
   'Batas dosis seluruh tubuh pekerja radiasi adalah 50 mSv (5 rem) per tahun. 1 mSv adalah batas untuk masyarakat umum.', 'Keselamatan Radiasi', 'medium'),
  ('Batas dosis radiasi tahunan untuk masyarakat umum (public) adalah:',
   '["50 mSv per tahun","5 mSv per tahun","1 mSv per tahun","0,5 mSv per bulan"]', 2,
   'Batas untuk masyarakat umum sangat ketat, yaitu 1 mSv (0,1 rem) per tahun. 50 mSv adalah batas pekerja dan 0,5 mSv/bulan adalah batas pekerja hamil yang dideklarasikan.', 'Keselamatan Radiasi', 'medium'),
  ('Untuk pekerja wanita yang telah mendeklarasikan kehamilan, batas dosis total sepanjang kehamilan adalah:',
   '["50 mSv","5 mSv","1 mSv per bulan","20 mSv"]', 1,
   'Pekerja hamil yang dideklarasikan dibatasi 0,5 mSv per bulan dengan total 5 mSv sepanjang kehamilan untuk melindungi janin.', 'Keselamatan Radiasi', 'hard'),
  ('Sebelum mendekati sumber gamma, alat yang dipakai untuk memastikan area benar-benar ''cold'' (aman) adalah:',
   '["Densitometer","Lux meter","Penetrameter","Survey meter (Geiger/ion chamber)"]', 3,
   'Survey meter (Geiger counter atau ion chamber) dipakai untuk men-survey area dan memverifikasi sumber sudah aman sebelum approach. Densitometer membaca density film, lux meter mengukur cahaya.', 'Keselamatan Radiasi', 'easy'),
  ('Saat melakukan crank source gamma, source macet dan tidak bisa kembali ke posisi shielded. Tindakan yang benar adalah:',
   '["Lanjutkan exposure berikutnya seperti biasa","Tarik kabel sekuat tenaga sampai source bergerak","Evakuasi dan isolasi area, lalu segera panggil RSO — ini keadaan darurat","Tinggalkan lokasi dan laporkan keesokan harinya"]', 2,
   'Source stuck adalah keadaan darurat: area harus dievakuasi dan diisolasi, lalu RSO segera dipanggil. Menarik kabel sekuat tenaga atau melanjutkan kerja membahayakan jiwa.', 'Keselamatan Radiasi', 'medium'),
  ('Penyimpanan sumber radiasi yang benar adalah:',
   '["Di laci meja biasa tanpa tanda","Di area terbuka dekat pekerja agar mudah diambil","Di dalam tas kain bersama film","Dalam shielded container terkunci dengan radiation symbol dan inventory check tiap shift"]', 3,
   'Sumber harus disimpan dalam kontainer berperisai (shielded), terkunci, diberi simbol radiasi, dan diperiksa inventarisnya setiap shift untuk mencegah kehilangan dan paparan.', 'Keselamatan Radiasi', 'easy'),
  ('Pada klasifikasi industrial film, jenis film yang memberikan kontras tertinggi namun butuh exposure paling lama adalah:',
   '["Class T4 (coarse grain)","Class T1 (ultra-fine grain)","Class T3 (medium grain)","Fluorescent screen film"]', 1,
   'Class T1 (ultra-fine grain) memberi kontras tertinggi namun butuh exposure paling lama, dipakai untuk aerospace/nuclear. Class T4 paling cepat tetapi kontrasnya paling rendah.', 'Film & Detektor', 'medium'),
  ('Fungsi lead screen (foil timbal) yang ditempatkan di sisi depan dan belakang film adalah:',
   '["Mengurangi scattered radiation dan menambah ketajaman citra","Mengubah X-ray menjadi cahaya untuk mempercepat exposure","Mengukur optical density film","Menahan dosis radiasi yang diterima operator"]', 0,
   'Lead screen mengurangi hamburan (scattered radiation) dan menambah ketajaman citra. Yang mengubah X-ray menjadi cahaya untuk mempercepat exposure adalah fluorescent/salt screen, dengan konsekuensi resolusi menurun.', 'Film & Detektor', 'medium'),
  ('Apa perbedaan utama DR (Direct Radiography) dengan CR (Computed Radiography)?',
   '["DR memakai film basah, CR memakai film kering","DR hanya untuk gamma, CR hanya untuk X-ray","DR menghasilkan citra digital langsung dari flat panel, CR memakai imaging plate yang di-scan setelah exposure","DR tidak menghasilkan citra digital sama sekali"]', 2,
   'DR memakai detektor flat panel yang langsung menghasilkan citra digital real-time, sedangkan CR memakai imaging plate fosfor yang harus di-scan setelah exposure dan dapat dipakai ulang.', 'Film & Detektor', 'medium'),
  ('Apa fungsi utama Image Quality Indicator (IQI / penetrameter) pada radiograph?',
   '["Mengukur dosis radiasi yang diterima operator","Memverifikasi kualitas/sensitivitas radiograph melalui visibilitas wire atau hole","Menggantikan densitometer","Menahan scattered radiation"]', 1,
   'IQI adalah alat kalibrasi yang ditempatkan dalam radiograph; visibilitas wire/hole terkecil membuktikan sensitivitas dan kualitas citra memadai. IQI bukan alat dosimetri atau penahan radiasi.', 'IQI', 'easy'),
  ('Penempatan IQI yang menjadi standar utama menurut code adalah di sisi:',
   '["Source-side (sisi sumber)","Film-side tanpa marker","Di luar area weld","Menempel pada survey meter"]', 0,
   'IQI standar ditempatkan di source-side karena merupakan kondisi paling sulit (terjauh dari film). Penempatan film-side hanya dipakai jika source-side tidak praktis dan harus diberi marker huruf ''F''.', 'IQI', 'medium'),
  ('Pada hole-type IQI, istilah ''2T'' mengacu pada hole dengan diameter sebesar:',
   '["Setengah ketebalan IQI plate","2 mm tetap","2 kali ketebalan IQI plate","2 kali ketebalan part yang diinspeksi"]', 2,
   'Pada hole-type IQI, ''2T'' berarti diameter hole sama dengan 2 kali ketebalan plate IQI. Visibilitas hole 2T menjadi acuan tingkat sensitivitas yang dicapai.', 'IQI', 'hard'),
  ('Jika ketebalan part 10 mm dan diameter wire terkecil yang terlihat adalah 0,2 mm, berapa persen sensitivitas radiograph?',
   '["0,2%","2%","5%","20%"]', 1,
   'Sensitivitas = (diameter wire terlihat / ketebalan) x 100 = (0,2 / 10) x 100 = 2%. Ini sesuai target sensitivitas yang baik (~2%).', 'IQI', 'hard'),
  ('Rumus geometric unsharpness (Ug) yang benar adalah:',
   '["Ug = F x SOD / OFD","Ug = F x OFD / SOD","Ug = SOD / (F x OFD)","Ug = OFD x SOD / F"]', 1,
   'Ug = F x OFD / SOD, dengan F = ukuran focal spot, OFD = jarak objek ke film, SOD = jarak sumber ke objek. Memperbesar SOD dan memperkecil OFD menurunkan Ug.', 'Geometric Unsharpness', 'easy'),
  ('Diketahui F = 3 mm, OFD = 20 mm, dan SOD = 500 mm. Berapa nilai Ug?',
   '["0,06 mm","0,12 mm","0,24 mm","1,2 mm"]', 1,
   'Ug = F x OFD / SOD = (3 x 20) / 500 = 60 / 500 = 0,12 mm. Nilai ini di bawah batas umum ASME V sebesar 0,5 mm untuk ketebalan <=2 inch.', 'Geometric Unsharpness', 'hard'),
  ('Cara yang benar untuk mengurangi geometric unsharpness (Ug) adalah:',
   '["Memperbesar OFD dan memperkecil SOD","Menaikkan kV setinggi mungkin","Memperbesar focal spot size","Memperbesar SOD dan memperkecil OFD (objek serapat mungkin ke film)"]', 3,
   'Karena Ug = F x OFD / SOD, menambah SOD dan mengurangi OFD (objek dirapatkan ke film) akan menurunkan Ug. Memperbesar OFD/focal spot atau menaikkan kV justru memperburuk atau tidak relevan.', 'Geometric Unsharpness', 'medium'),
  ('Apa definisi Half-Value Layer (HVL)?',
   '["Tebal material yang mengurangi intensitas radiasi menjadi 50%","Tebal material yang menyerap seluruh radiasi","Jarak ganda dari sumber ke film","Waktu yang dibutuhkan untuk separuh exposure"]', 0,
   'HVL adalah tebal material yang mengurangi intensitas radiasi menjadi 50%, bersifat spesifik untuk tiap material dan energi. Berguna untuk perhitungan shielding dan transmisi.', 'Exposure & HVL', 'easy'),
  ('Rentang optical density yang dapat diterima untuk radiograph X-ray menurut ASME V umumnya adalah:',
   '["0,5–1,0","1,8–4,0","5,0–8,0","0,1–0,5"]', 1,
   'ASME V mensyaratkan density 1,8–4,0 untuk X-ray (2,0–4,0 untuk gamma). Di luar rentang ini radiograph harus di-shoot ulang.', 'Exposure & Density', 'medium'),
  ('Urutan proses kimia pengembangan film radiografi yang benar adalah:',
   '["Fixer → Developer → Wash → Stop bath → Dry","Wash → Fixer → Developer → Dry → Stop bath","Developer → Stop bath → Fixer → Wash → Dry","Developer → Fixer → Stop bath → Dry → Wash"]', 2,
   'Urutan yang benar adalah Developer (ubah silver halide tereksposur menjadi metallic silver) → Stop bath (hentikan reaksi) → Fixer (larutkan halide tak tereksposur) → Wash → Dry.', 'Pengembangan Film', 'hard'),
  ('Cacat las yang tampak sebagai garis gelap linear sangat tajam, sering bercabang, dan paling kritikal adalah:',
   '["Porosity","Slag inclusion","Crack","Undercut"]', 2,
   'Crack tampak sebagai garis gelap linear yang sangat tajam dan sering bercabang; ini cacat paling kritikal dan selalu ditolak. Porosity berbentuk bulat dan slag berbentuk memanjang tidak beraturan.', 'Interpretasi Cacat', 'easy'),
  ('Pada radiograph, cacat porosity biasanya tampak sebagai:',
   '["Indikasi bulat (round), gelap, dengan tepi tajam, tersebar atau menggerombol","Garis lurus sangat tajam yang bercabang","Indikasi memanjang tidak beraturan di dalam weld","Area lebih terang dari base metal"]', 0,
   'Porosity tampak sebagai indikasi bulat gelap bertepi tajam, bisa tunggal atau cluster, karena merupakan rongga gas. Garis bercabang tajam adalah crack, dan indikasi memanjang tak beraturan adalah slag.', 'Interpretasi Cacat', 'easy'),
  ('Lack of penetration (LOP) pada radiograph weld biasanya muncul sebagai:',
   '["Bintik bulat tersebar di seluruh weld","Garis gelap linear di centerline (root) dengan tepi tajam","Area lebih terang merata","Pola titik fluorescent"]', 1,
   'LOP tampak sebagai garis gelap linear di centerline/root weld dengan tepi tajam, sering sangat gelap karena void-nya besar. Bintik bulat adalah porosity.', 'Interpretasi Cacat', 'medium'),
  ('Lack of fusion (LOF) pada radiograph paling sering ditemukan di lokasi:',
   '["Sidewall weld, tampak linear gelap namun subtle","Tepat di permukaan plate luar","Hanya di base metal jauh dari weld","Selalu di pusat lubang bor"]', 0,
   'LOF muncul sebagai indikasi linear gelap di sidewall weld dan sifatnya subtle, sehingga operator harus paham lokasi tipikalnya. LOP justru muncul di centerline/root.', 'Interpretasi Cacat', 'hard'),
  ('Manakah yang merupakan film artifact, bukan cacat material sebenarnya?',
   '["Crimp mark, fingerprint, atau water spot pada film","Porosity bulat di tengah weld","Lack of penetration di root","Slag memanjang di dalam weld"]', 0,
   'Crimp mark, fingerprint, dan water spot adalah artifact film yang berpola tidak natural (garis lurus, berulang). Porosity, LOP, dan slag adalah cacat material asli.', 'Interpretasi Cacat', 'easy'),
  ('Pada radiograph casting, inclusion berupa material asing yang lebih padat dari base metal akan tampak:',
   '["Lebih terang (lighter) dari base metal","Lebih gelap (darker) dari base metal","Tidak terlihat sama sekali","Berwarna merah cerah"]', 0,
   'Inclusion dengan densitas lebih tinggi menyerap lebih banyak radiasi sehingga tampak lebih terang dari base metal. Inclusion berdensitas rendah (mis. void) justru tampak lebih gelap.', 'Interpretasi Cacat', 'hard'),
  ('Code yang menjadi acuan utama RT untuk pressure equipment, berisi parameter dan acceptance detail, adalah:',
   '["ASME Section V Article 2","AWS D1.1","ASTM E709","ISO 9934"]', 0,
   'ASME Section V Article 2 mengatur RT untuk pressure equipment dengan parameter dan acceptance terperinci. AWS D1.1 untuk struktur baja, sedangkan E709/ISO 9934 adalah standar MT.', 'Prosedur & Code', 'medium'),
  ('Menurut acceptance criteria umum (mis. ASME), cacat yang otomatis REJECT tanpa memandang ukuran adalah:',
   '["Porosity tunggal kecil","Variasi penguatan weld minor","Density gradient ringan","Crack"]', 3,
   'Crack (dan lack of fusion) bersifat reject otomatis karena tajam dan menjalar. Porosity/slag dinilai berdasarkan ukuran dan frekuensi per ketebalan, sedangkan density gradient ringan masih bisa diterima.', 'Prosedur & Code', 'easy'),
  ('Langkah post-job yang benar terkait sumber gamma setelah exposure selesai adalah:',
   '["Tinggalkan source di posisi exposure agar siap dipakai lagi","Simpan source di saku selama perjalanan pulang","Crank source kembali ke posisi shielded, verify ''cold'' dengan survey meter, lalu kunci storage","Lepas perisai agar source cepat dingin"]', 2,
   'Setelah selesai, source di-crank kembali ke posisi berperisai, diverifikasi ''cold'' dengan survey meter, lalu storage dikunci. Meninggalkan source terbuka atau membawanya tanpa perisai sangat berbahaya.', 'Praktik Lapangan', 'easy'),
  ('Informasi berikut yang WAJIB ada dalam RT report adalah:',
   '["Hanya tanda tangan inspektor","Source type & activity, film type, kV/mA/time, distance, IQI sensitivity, density, dan temuan cacat","Hanya tanggal pengujian","Warna cat permukaan part"]', 1,
   'RT report harus memuat data peralatan (source, film, kV/mA/time, distance), kualitas (IQI/sensitivity, density), temuan cacat dengan klasifikasi dan accept/reject, serta sign-off. Hanya tanggal/tanda tangan saja tidak memadai.', 'Reporting & Arsip', 'medium'),
  ('Kondisi penyimpanan film radiograph untuk arsip jangka panjang yang benar adalah:',
   '["Cool, dry, dalam archival sleeve dengan retensi sesuai code/kontrak (mis. 5 tahun)","Di tempat lembap dan panas agar awet","Ditumpuk tanpa pelindung di lantai","Dibuang setelah laporan dibuat"]', 0,
   'Film disimpan di tempat sejuk dan kering dalam archival sleeve dengan masa retensi sesuai code/kontrak (umumnya 5 tahun). Kelembapan/panas merusak film dan membuang film menghilangkan rekaman permanen.', 'Reporting & Arsip', 'easy')
) AS q(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L1' AND m."orderIndex" = 14 AND ls."orderIndex" = 2 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ============================================
-- VT-L1 FINAL ASSESSMENT (module 6, step 3) — 40 questions
-- ============================================
-- Idempotent: clear any previously-seeded questions for this final-assessment step first.
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L1' AND m."orderIndex" = 6 AND ls."orderIndex" = 3 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, q.question, q.options::jsonb, q."correctAnswer", q.explanation, q.category, 'VT', 'Level I', q.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Mengapa Visual Testing (VT) sering disebut sebagai metode NDT yang paling fundamental?',
   '["Karena VT mampu mendeteksi cacat internal di tengah material","Karena VT tidak memerlukan inspector bersertifikat","Karena VT selalu dilakukan terlebih dahulu untuk mendeteksi cacat permukaan sebelum metode lain","Karena VT menggantikan kebutuhan semua metode NDT lainnya"]', 2,
   'VT adalah metode NDT pertama dan paling fundamental yang selalu dilakukan lebih dulu untuk menemukan cacat permukaan yang jelas. VT hanya mendeteksi cacat permukaan, bukan internal, dan tetap membutuhkan inspector bersertifikat serta tidak menggantikan metode lain.', 'Principles', 'easy'),
  ('Pernyataan mana yang paling tepat menggambarkan Visual Testing yang benar?',
   '["Inspeksi sistematis dengan kriteria penerimaan, dokumentasi, dan tools seperti kaca pembesar dan gauge","Sekadar melihat permukaan secara sekilas tanpa alat","Hanya boleh dilakukan dengan kamera digital","Selalu memerlukan ruang gelap dan lampu UV"]', 0,
   'VT yang benar adalah inspeksi sistematis dengan kriteria penerimaan jelas, dokumentasi, dan penggunaan tools (kaca pembesar, mistar, gauge), bukan sekadar melihat sekilas. Ruang gelap/UV hanya diperlukan pada VT fluorescent tertentu.', 'Principles', 'easy'),
  ('Manakah yang termasuk aplikasi umum Visual Testing?',
   '["Hanya pengukuran ketebalan dinding pipa","Deteksi cacat internal pada coran tebal","Pengukuran konduktivitas material","Pre-weld inspection, post-weld inspection, dan in-service inspection"]', 3,
   'VT digunakan untuk pre-weld inspection, post-weld inspection, in-service inspection, dan evaluasi fitness-for-service. Pengukuran ketebalan internal dan konduktivitas adalah ranah metode lain (UT dan ET).', 'Principles', 'easy'),
  ('Apa perbedaan utama antara direct visual inspection dan remote visual inspection?',
   '["Direct memakai borescope, remote memakai mata telanjang","Direct hanya untuk las, remote hanya untuk coran","Direct memandang permukaan langsung dengan mata (jarak <=600 mm), remote memakai alat seperti borescope untuk area yang tak terjangkau","Remote tidak memerlukan pencahayaan minimum"]', 2,
   'Direct visual berarti mata memandang permukaan secara langsung (jarak <=600 mm, sudut >=30 derajat), sedangkan remote visual memakai borescope/fiberscope/kamera untuk mengakses area sempit atau tersembunyi. Syarat pencahayaan tetap berlaku pada keduanya.', 'Technique', 'easy'),
  ('Pada direct visual inspection, berapa jarak maksimum mata inspector terhadap permukaan menurut ASME V Article 9?',
   '["<= 300 mm (12 inch)","<= 900 mm (36 inch)","<= 1200 mm (48 inch)","<= 600 mm (24 inch)"]', 3,
   'ASME V Article 9 menetapkan jarak mata maksimum <=600 mm (24 inch) dari permukaan inspeksi pada direct visual. Jarak yang lebih jauh mengurangi resolusi detail cacat halus.', 'Technique', 'easy'),
  ('Berapa sudut pandang minimum terhadap permukaan pada direct visual inspection per ASME V Article 9?',
   '[">= 30 derajat",">= 10 derajat",">= 20 derajat",">= 45 derajat"]', 0,
   'Sudut pandang minimum adalah >=30 derajat terhadap permukaan. Sudut terlalu landai membuat detail cacat sulit dilihat dan menimbulkan distorsi pengamatan.', 'Technique', 'easy'),
  ('Berapa intensitas cahaya minimum yang disyaratkan pada permukaan inspeksi VT menurut ASME V dan AWS D1.1?',
   '["500 lux","1000 lux","750 lux","2000 lux"]', 1,
   'Minimum 1000 lux pada permukaan inspeksi disyaratkan oleh ASME V dan AWS D1.1. Nilai di bawah itu tidak cukup untuk mendeteksi cacat permukaan secara andal.', 'Standards', 'easy'),
  ('Untuk mendeteksi crack yang sangat halus, tingkat pencahayaan optimal yang dianjurkan adalah?',
   '["1000 lux","1500-2000 lux","8000-10000 lux","3000-5000 lux"]', 3,
   'Pencahayaan optimal 3000-5000 lux dianjurkan untuk inspeksi crack halus, idealnya dengan high-CRI LED agar warna akurat. 1000 lux hanyalah batas minimum, bukan optimal.', 'Equipment', 'medium'),
  ('Seberapa sering eye examination wajib dilakukan oleh inspector VT?',
   '["Setiap bulan","Setiap 3 tahun","Setiap tahun (annual)","Hanya sekali saat sertifikasi awal"]', 2,
   'Inspector wajib menjalani eye exam setiap tahun (annual), meliputi near vision (Jaeger 2 atau Snellen 20/40) dan pemeriksaan persepsi warna. Pemeriksaan sekali saja tidak cukup karena ketajaman penglihatan dapat menurun.', 'Standards', 'medium'),
  ('Standar near vision yang harus dipenuhi inspector VT pada eye exam tahunan adalah?',
   '["Jaeger 2 atau Snellen 20/40","Jaeger 5 atau Snellen 20/100","Jaeger 1 atau Snellen 20/20","Tidak ada standar baku, tergantung inspector"]', 0,
   'Standar near vision adalah Jaeger 2 atau Snellen 20/40, dengan atau tanpa kacamata. Persepsi warna juga harus diperiksa. Snellen 20/100 terlalu longgar dan 20/20 tidak diwajibkan.', 'Standards', 'medium'),
  ('Alat remote visual mana yang menggunakan tube rigid dengan kombinasi lens dan prism, cocok untuk lubang lurus seperti tube?',
   '["Fiberscope","Pan-tilt camera","Borescope rigid","Pit gauge"]', 2,
   'Borescope rigid adalah tube kaku dengan optik (lens & prism) di dalam untuk angle view, cocok untuk lubang lurus. Fiberscope fleksibel untuk lubang berkelok, dan pan-tilt camera untuk vessel internal.', 'Equipment', 'medium'),
  ('Alat remote visual mana yang menggunakan fiber optik fleksibel sehingga bisa masuk lubang berkelok, namun resolusinya lebih rendah dari rigid borescope?',
   '["Video borescope","Pan-tilt crawler","Dental mirror","Fiberscope"]', 3,
   'Fiberscope memakai fiber optik fleksibel yang dapat masuk lubang berkelok, tetapi resolusinya lebih rendah dibanding rigid borescope. Video borescope justru memberikan citra digital modern dengan kualitas baik.', 'Equipment', 'medium'),
  ('Alat remote visual mana yang menjadi standar untuk inspeksi turbine karena memiliki camera CCD/CMOS di tip dengan output video digital dan kemampuan recording?',
   '["Video borescope","Borescope rigid","Fiberscope","Plain mirror"]', 0,
   'Video borescope memiliki camera CCD/CMOS di tip dengan video output digital dan recording capability, menjadi standar untuk turbine inspection. Rigid dan fiberscope bersifat optik murni tanpa kamera digital di tip.', 'Equipment', 'medium'),
  ('Untuk inspeksi internal pressure vessel atau tank floor area yang luas, alat remote visual mana yang paling tepat?',
   '["Magnifier genggam 3-10x","Dental mirror","Bridge cam gauge","Pan-tilt camera pada robotic crawler"]', 3,
   'Pan-tilt camera pada robotic crawler dirancang untuk pressure vessel internal dan tank floor yang luas dan sulit dijangkau manusia. Magnifier, mirror, dan welding gauge adalah alat manual jarak dekat.', 'Equipment', 'medium'),
  ('Perbesaran magnifier yang umum dipakai untuk inspeksi crack halus pada VT adalah?',
   '["1-2x","3-10x","20-50x","100-200x"]', 1,
   'Magnifier 3-10x umum dipakai untuk inspeksi crack halus pada VT. Perbesaran yang sangat tinggi (>50x) lebih ke ranah mikroskopi/metalografi, bukan VT lapangan Level I.', 'Equipment', 'easy'),
  ('Alat mana yang digunakan khusus untuk mengukur kedalaman (depth) pitting akibat korosi?',
   '["Fillet gauge","Bridge cam gauge","Pit gauge","Lux meter"]', 2,
   'Pit gauge (tersedia tipe digital maupun analog dial) dipakai untuk mengukur depth pitting korosi. Fillet/bridge cam gauge mengukur profil las, sedangkan lux meter mengukur intensitas cahaya.', 'Equipment', 'easy'),
  ('Bridge cam gauge dan fillet gauge termasuk dalam kategori alat untuk?',
   '["Mengukur intensitas cahaya permukaan","Mengukur profil las (weld profile)","Mengukur kedalaman korosi","Mendeteksi medan magnet bocor"]', 1,
   'Bridge cam gauge dan fillet gauge adalah welding gauge untuk mengukur profil las seperti leg length, throat, dan reinforcement. Cahaya diukur dengan lux meter dan pitting dengan pit gauge.', 'Equipment', 'easy'),
  ('Penggunaan plain mirror atau dental mirror dalam VT paling tepat untuk?',
   '["Mengukur intensitas cahaya","Mengukur kedalaman pitting","Menggantikan eye exam tahunan","Mengakses dan melihat sudut/sisi belakang yang tidak terlihat langsung"]', 3,
   'Mirror digunakan untuk mengakses sudut atau sisi belakang yang tidak terlihat langsung, dan idealnya dipakai bersama light source langsung. Mirror bukan alat ukur cahaya maupun kedalaman.', 'Equipment', 'easy'),
  ('Bagaimana cara memverifikasi bahwa intensitas cahaya memenuhi syarat saat inspeksi VT?',
   '["Memperkirakan secara visual oleh inspector","Mengandalkan spesifikasi watt lampu yang dipasang","Mengukur dengan lux meter tepat di permukaan inspeksi, bukan ambient umum","Cukup memastikan ruangan tidak gelap"]', 2,
   'Lux meter harus mengukur cahaya tepat di permukaan inspeksi (bukan ambient umum) dan harus dikalibrasi (umumnya tahunan). Perkiraan visual atau spesifikasi watt lampu tidak menjamin 1000 lux pada titik kerja.', 'Technique', 'hard'),
  ('Berapa nilai minimum Color Rendering Index (CRI) sumber cahaya untuk inspeksi VT umum?',
   '["Minimum 50","Minimum 80","Minimum 95","Tidak ada syarat CRI"]', 1,
   'CRI minimum 80 disyaratkan untuk inspeksi umum, sedangkan CRI 90+ dianjurkan untuk identifikasi warna yang kritis. CRI yang terlalu rendah menyebabkan warna tampak terdistorsi.', 'Equipment', 'hard'),
  ('Apa dampak glare (silau dari cahaya pantul yang terlalu kuat) terhadap inspeksi VT?',
   '["Meningkatkan kontras retak halus","Tidak berpengaruh selama lux meter membaca >1000 lux","Membuat mata cepat lelah dan dapat menyembunyikan cacat","Membuat permukaan tampak lebih gelap dari sebenarnya"]', 2,
   'Glare menyebabkan silau yang membuat mata cepat lelah dan dapat menutupi cacat; solusinya adalah menyesuaikan sudut cahaya atau memakai diffuse light. Glare justru menurunkan, bukan meningkatkan, kemampuan deteksi.', 'Technique', 'medium'),
  ('Dalam surface preparation untuk VT, apa yang umumnya harus dihilangkan dari permukaan?',
   '["Hanya debu kasar saja","Dirt, oil, scale, dan paint (kecuali acceptance mengizinkan paint)","Logam dasar di sekitar las","Marking pen referensi"]', 1,
   'Permukaan harus dibersihkan dari dirt, oil, scale, dan paint, kecuali bila kriteria penerimaan memang mengizinkan paint tetap ada. Marking pen referensi justru sengaja ditambahkan untuk dokumentasi.', 'Technique', 'easy'),
  ('Saat VT digabung dengan fluorescent dye, berapa intensitas minimum lampu UV-A yang disyaratkan?',
   '["1000 microW/cm2 dengan booth gelap","100 microW/cm2 di ruang terang","500 lux putih biasa","Tidak ada syarat, cukup cahaya tampak 1000 lux"]', 0,
   'VT fluorescent membutuhkan lampu UV-A minimum 1000 microW/cm2 dengan booth gelap agar indikasi fluoresen tampak kontras. Cahaya tampak biasa atau intensitas UV yang rendah tidak akan memunculkan indikasi dengan jelas.', 'Equipment', 'medium'),
  ('Apa fungsi marking dengan pen marker pada area inspeksi VT?',
   '["Menggantikan laporan tertulis","Meningkatkan intensitas cahaya","Memberi reference line, dimensi, dan lokasi defect","Membersihkan scale dari permukaan"]', 2,
   'Pen marker dipakai untuk menandai reference line, dimensi, dan lokasi defect (permanent atau temporary), bukan untuk menggantikan laporan atau membersihkan permukaan.', 'Documentation', 'easy'),
  ('Pada fillet weld, dimensi las umumnya diukur dengan?',
   '["Density radiograph","Leg length atau throat thickness","Skin depth","Half-life sumber"]', 1,
   'Fillet weld (las antara dua permukaan tegak lurus) diukur dengan leg length atau throat thickness menggunakan fillet/welding gauge. Density, skin depth, dan half-life adalah parameter metode lain.', 'Defects', 'medium'),
  ('Pada full penetration groove weld, di mana inspeksi visual seharusnya dilakukan?',
   '["Hanya di sisi face","Hanya di sisi root","Di kedua sisi (face dan root)","Hanya pada base metal di luar las"]', 2,
   'Groove weld full penetration harus diinspeksi di kedua sisi, yaitu face dan root, karena las menembus penuh. Memeriksa satu sisi saja berisiko melewatkan cacat di sisi lainnya.', 'Defects', 'medium'),
  ('Apa ciri utama partial penetration weld dibanding full penetration?',
   '["Selalu lebih kuat dari full penetration","Tidak boleh memiliki reinforcement","Wajib diinspeksi dengan UT saja","Terdapat unfused portion pada root yang penerimaannya bergantung pada desain"]', 3,
   'Partial penetration weld tidak menembus penuh sehingga ada unfused portion di root, dan penerimaannya ditentukan per desain. Ini bukan cacat otomatis jika memang sesuai rancangan, dan tetap bisa diinspeksi secara visual.', 'Defects', 'medium'),
  ('Apa yang dimaksud dengan undercut pada las?',
   '["Weld metal yang meluap ke base metal tanpa fusion","Cap las yang terlalu tinggi","Groove (alur) pada base metal di sebelah weld toe yang mengurangi cross-section","Depresi bulat di permukaan las"]', 2,
   'Undercut adalah groove pada base metal di sebelah weld toe yang mengurangi cross-section dan menjadi stress concentration. Weld metal meluap tanpa fusion adalah overlap, sedangkan cap terlalu tinggi adalah excessive reinforcement.', 'Defects', 'easy'),
  ('Cacat las berupa weld metal yang meluap (overflow) ke base metal tanpa terjadi fusion disebut?',
   '["Undercut","Overlap","Crater crack","Porosity"]', 1,
   'Overlap adalah weld metal yang overflow ke base metal tanpa fusion, membentuk crevice yang dapat menampung media korosif. Undercut justru berupa alur, bukan overflow.', 'Defects', 'easy'),
  ('Crack yang muncul di ujung (end) suatu weld pass, sering berbentuk star shape, disebut?',
   '["Undercut","Excessive reinforcement","Overlap","Crater crack"]', 3,
   'Crater crack adalah retak di end of weld pass yang sering berbentuk bintang (star shape), umumnya akibat pendinginan cepat di crater. Distraktor lain bukan retak ujung pass.', 'Defects', 'medium'),
  ('Mengapa excessive reinforcement (cap las terlalu tinggi) dianggap sebagai cacat?',
   '["Karena mengurangi cross-section las","Karena menjadi fatigue concern / stress raiser","Karena selalu menyebabkan porosity","Karena menurunkan intensitas cahaya inspeksi"]', 1,
   'Excessive reinforcement membuat cap las terlalu tinggi sehingga menjadi fatigue concern karena transisi tajam berperan sebagai stress raiser. Ini menambah, bukan mengurangi, material di cap.', 'Defects', 'medium'),
  ('Cacat permukaan las berupa depresi bulat (round depression) di permukaan weld disebut?',
   '["Pit/blowhole","Undercut","Overlap","Crater crack"]', 0,
   'Pit atau blowhole adalah round depression di permukaan las akibat gas yang terperangkap. Undercut berupa alur memanjang dan crater crack berupa retak bintang di ujung pass.', 'Defects', 'easy'),
  ('Menurut AWS D1.1 untuk sambungan statically loaded dengan thickness > 25 mm, berapa kedalaman undercut maksimum yang masih dapat diterima?',
   '["0,25 mm","0,5 mm","1 mm","2 mm"]', 2,
   'Untuk statically loaded dengan thickness > 25 mm, AWS D1.1 mengizinkan undercut maksimum 1 mm. Nilai 0,25 mm adalah batas yang lebih ketat untuk kondisi cyclically loaded.', 'Standards', 'hard'),
  ('Untuk sambungan cyclically loaded menurut AWS D1.1, berapa kedalaman undercut maksimum yang diizinkan?',
   '["1 mm","0,25 mm","1,5 mm","3 mm"]', 1,
   'Cyclically loaded memiliki kriteria lebih ketat: undercut maksimum 0,25 mm, dan profil harus smooth transition. Beban siklik sangat sensitif terhadap stress concentration sehingga toleransinya lebih kecil.', 'Standards', 'hard'),
  ('Menurut AWS D1.1, bagaimana penerimaan crack (retak) pada las?',
   '["Diterima jika kedalaman < 1 mm","Diterima jika hanya di base metal","Diterima untuk statically loaded saja","REJECT semua, tanpa pengecualian"]', 3,
   'Crack di-REJECT semua tanpa pengecualian menurut AWS D1.1, baik statically maupun cyclically loaded. Retak adalah cacat paling kritis karena cenderung merambat di bawah beban.', 'Standards', 'hard'),
  ('Mengapa convexity berlebih pada fillet weld dibatasi oleh AWS D1.1?',
   '["Karena menambah penetrasi root","Karena mengurangi leg length","Karena excess convexity menjadi stress raiser","Karena menyebabkan undercut otomatis"]', 2,
   'Convexity fillet weld tidak boleh melebihi rumus AWS karena kelebihan convexity menjadi stress raiser pada transisi toe. Convexity tidak menambah penetrasi root maupun otomatis menimbulkan undercut.', 'Standards', 'hard'),
  ('Informasi mana yang wajib ada pada header sebuah laporan VT?',
   '["Hanya nama inspector saja","Hanya hasil accept/reject","Project, weld ID, drawing, procedure, date, dan inspector cert","Spesifikasi merk lampu yang dipakai"]', 2,
   'Header laporan VT mencakup project, weld ID, drawing, procedure, date, dan inspector cert sebagai informasi identifikasi dan traceability. Hasil accept/reject masuk di bagian findings, bukan header.', 'Documentation', 'medium'),
  ('Bagian findings pada laporan VT seharusnya mencantumkan?',
   '["Defect type, lokasi (datum reference), dimensi, dan accept/reject per code","Hanya foto tanpa keterangan","Daftar harga peralatan","Riwayat eye exam inspector"]', 0,
   'Findings harus memuat defect type, lokasi dengan datum reference, dimensi, serta keputusan accept/reject per code agar laporan jelas dan dapat ditelusuri. Foto tanpa keterangan tidak memenuhi standar pelaporan.', 'Documentation', 'medium'),
  ('Selain header dan findings, bagian sign-off pada laporan VT wajib memuat?',
   '["Nama dan level inspector, supervisor, serta tanggal","Hanya nomor halaman","Daftar weld berikutnya","Spesifikasi lux meter saja"]', 0,
   'Bagian sign-off mencantumkan inspector beserta level-nya, supervisor, dan tanggal sebagai pengesahan dan pertanggungjawaban laporan. Tanpa sign-off, laporan tidak sah secara administratif.', 'Documentation', 'medium'),
  ('Standar simbol las yang dipakai pada sketch laporan VT mengacu pada?',
   '["AWS A2.4","ASME V Article 9","ISO 9712","Jaeger chart"]', 0,
   'Simbol las pada sketch mengikuti AWS A2.4 agar konsisten dengan standar industri. ASME V Article 9 mengatur teknik VT, ISO 9712 mengatur sertifikasi personel, dan Jaeger chart untuk eye exam.', 'Documentation', 'hard')
) AS q(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L1' AND m."orderIndex" = 6 AND ls."orderIndex" = 3 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ============================================
-- ET-L1 FINAL ASSESSMENT (module 9, step 2) — 40 questions
-- ============================================
-- Idempotent: clear any previously-seeded questions for this final-assessment step first.
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L1' AND m."orderIndex" = 9 AND ls."orderIndex" = 2 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, q.question, q.options::jsonb, q."correctAnswer", q.explanation, q.category, 'ET', 'Level I', q.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Prinsip fisika yang menjadi dasar semua Eddy Current Testing adalah...',
   '["Induksi elektromagnetik (hukum Faraday)","Refleksi gelombang suara","Kapilaritas cairan","Atenuasi radiasi gamma"]', 0,
   'ET berlandaskan induksi elektromagnetik: perubahan medan magnet dari coil AC menginduksi tegangan dan eddy current di material konduktif (hukum Faraday). Refleksi suara adalah UT, kapilaritas adalah PT, dan atenuasi radiasi adalah RT.', 'Prinsip Dasar', 'easy'),
  ('Jenis material apa yang DAPAT diinspeksi dengan Eddy Current Testing?',
   '["Plastik","Material konduktif listrik seperti aluminum dan baja","Keramik","Kayu"]', 1,
   'ET hanya bekerja pada material konduktif listrik (baja, aluminum, copper, brass, titanium) karena eddy current hanya dapat terinduksi pada konduktor. Plastik, keramik, dan kayu bukan konduktor sehingga tidak dapat diuji dengan ET.', 'Prinsip Dasar', 'easy'),
  ('Aplikasi terbesar Eddy Current Testing di industri adalah...',
   '["Pengukuran kekasaran permukaan beton","Deteksi kebocoran gas","Inspeksi tubing heat exchanger","Pengujian kekerasan baja"]', 2,
   'Aplikasi ET terbesar adalah inspeksi tubing heat exchanger karena tubing tersusun rapat dan tidak dapat diakses secara visual atau RT; bobbin probe ET menjadi satu-satunya cara feasibel. Opsi lain bukan aplikasi utama ET.', 'Aplikasi', 'easy'),
  ('Selain deteksi cacat, ET juga lazim dipakai untuk aplikasi pengukuran...',
   '["Kadar air dalam beton","Tingkat kebisingan mesin","Ketebalan coating non-konduktif di atas logam dan conductivity sorting","Suhu permukaan tungku"]', 2,
   'Karena lift-off berkaitan dengan jarak coil-logam, ET dipakai mengukur ketebalan coating non-konduktif di atas logam, dan perubahan konduktivitas dimanfaatkan untuk conductivity/material sorting. Kadar air, kebisingan, dan suhu bukan ranah ET.', 'Aplikasi', 'easy'),
  ('Apa yang sebenarnya diukur/berubah pada coil ketika eddy current terganggu oleh sebuah cacat?',
   '["Suhu coil","Massa coil","Warna coil","Impedansi coil"]', 3,
   'Cacat mengganggu pola eddy current sehingga medan oposisi berubah dan menyebabkan perubahan impedansi coil yang ditampilkan sebagai sinyal. Suhu, massa, dan warna coil tidak digunakan sebagai parameter deteksi.', 'Prinsip Dasar', 'easy'),
  ('Fenomena terkonsentrasinya eddy current di dekat permukaan material dan menurun secara eksponensial ke dalam disebut...',
   '["Lift-off effect","Skin effect","Lenz effect","Hall effect"]', 1,
   'Skin effect adalah kecenderungan eddy current terkonsentrasi dekat permukaan dan meluruh eksponensial terhadap kedalaman. Lift-off adalah perubahan jarak probe-permukaan, sedangkan Lenz dan Hall adalah fenomena lain.', 'Fisika ET', 'easy'),
  ('Surface probe (pencil probe) paling tepat digunakan untuk...',
   '["Inspeksi cepat seluruh keliling bar dalam satu pass","Inspeksi interior tube heat exchanger","Inspeksi titik per titik crack pada permukaan datar atau lengkung ringan","Mengukur dosis radiasi"]', 2,
   'Surface (pencil) probe berupa coil kecil di tip silindris untuk inspeksi titik per titik crack pada permukaan datar/lengkung ringan. Inspeksi keliling bar memakai encircling probe, interior tube memakai bobbin, dan dosis radiasi bukan ranah ET.', 'Probe', 'easy'),
  ('Bobbin probe pada inspeksi heat exchanger dimasukkan ke...',
   '["Bagian luar (OD) tube","Bagian dalam (interior/ID) tube","Antara dua tube sheet","Permukaan datar pelat"]', 1,
   'Bobbin probe adalah coil internal yang dimasukkan ke dalam (interior/ID) tube dan menjadi standar inspeksi heat exchanger. Encircling probe-lah yang melingkupi OD bar/rod, bukan bobbin.', 'Probe', 'easy'),
  ('Apa yang dimaksud dengan LIFT-OFF pada Eddy Current Testing?',
   '["Sudut datang gelombang suara","Tegangan baterai instrumen","Jarak antara coil dan permukaan material yang berubah-ubah","Suhu ruang inspeksi"]', 2,
   'Lift-off adalah jarak antara coil dan permukaan material; perubahan jarak ini mengubah impedansi dan bisa salah dibaca sebagai defect. Pilihan lain tidak berkaitan dengan definisi lift-off.', 'Probe', 'easy'),
  ('Pada impedance plane, sumbu mendatar (X) dan tegak (Y) masing-masing merepresentasikan...',
   '["X = perubahan resistance, Y = perubahan reactance","X = waktu, Y = amplitudo","X = frekuensi, Y = suhu","X = dosis, Y = jarak"]', 0,
   'Impedance plane adalah tampilan X-Y dengan sumbu X = perubahan resistance dan Y = perubahan reactance; setiap kondisi material/defect menjadi titik di plane. Sumbu lain (waktu, frekuensi, dosis) bukan definisi impedance plane.', 'Impedance Plane', 'easy'),
  ('Reference standard berupa notch presisi yang dibuat dengan electrical-discharge machining disebut...',
   '["FBH (flat bottom hole)","EDM notch","IQI","Step wedge"]', 1,
   'EDM notch adalah takik yang dimesin dengan electrical-discharge machining berdimensi presisi, menjadi standar reference untuk crack. FBH adalah lubang untuk defect volumetrik, sedangkan IQI dan step wedge adalah istilah dari metode lain.', 'Kalibrasi', 'easy'),
  ('Sebuah pit pada tube heat exchanger umumnya menghasilkan sinyal...',
   '["Tajam dan terlokalisasi (sharp localized)","Lebar dan bertahap (broad gradual)","Berulang teratur seperti support plate","Tidak menghasilkan sinyal apa pun"]', 0,
   'Pit menghasilkan sinyal tajam dan terlokalisasi karena defect-nya kecil dan lokal. Sinyal lebar bertahap menandakan wall loss umum, dan sinyal berulang teratur adalah support plate.', 'Interpretasi', 'easy'),
  ('Code utama yang mengatur Eddy Current Testing pada pressure equipment adalah...',
   '["ASME Section IX","AWS D1.1","API 1104","ASME Section V Article 8"]', 3,
   'ASME Section V Article 8 adalah code utama untuk ET pada pressure equipment. ASME IX mengatur kualifikasi welding, sedangkan AWS D1.1 dan API 1104 adalah code welding/pipeline, bukan ET.', 'Kode & Standar', 'easy'),
  ('Salah satu elemen yang WAJIB ada dalam written procedure ET adalah...',
   '["Scope berisi material, OD/ID tubing, ketebalan, dan jenis defect yang dicari","Resep makan siang teknisi","Merek mobil perusahaan","Jadwal libur nasional"]', 0,
   'Written procedure ET harus memuat scope (material, OD/ID tubing, ketebalan, jenis defect), equipment, kalibrasi, dan acceptance. Item non-teknis seperti resep, merek mobil, atau jadwal libur jelas bukan bagian prosedur.', 'Prosedur', 'easy'),
  ('Standar ASTM yang dipakai sebagai standard practice untuk inspeksi tubing dengan eddy current adalah...',
   '["ASTM E309","ASTM A36","ASTM D638","ASTM C150"]', 0,
   'ASTM E309 adalah standard practice untuk inspeksi tubing dengan eddy current (dan E243 untuk pipe & tube manufacturing). A36 spesifikasi baja struktural, D638 untuk plastik, C150 untuk semen - bukan standar ET.', 'Kode & Standar', 'easy'),
  ('Sebagai metode NDT, salah satu KEUNGGULAN keselamatan ET dibanding RT adalah...',
   '["ET tidak memerlukan akses ke kedua sisi benda uji","ET dapat menguji material non-konduktif","ET tidak memerlukan kalibrasi","ET tidak menggunakan radiasi pengion sehingga tidak ada bahaya radiasi"]', 3,
   'ET memakai medan elektromagnetik non-pengion, sehingga tidak ada bahaya radiasi seperti pada RT dan tidak perlu area terkontrol radiasi. ET justru terbatas pada material konduktif dan tetap memerlukan kalibrasi.', 'Keselamatan', 'easy'),
  ('Menurut hukum Lenz, eddy current yang terinduksi pada material akan mengalir dengan arah yang...',
   '["Searah dengan perubahan medan coil","Berlawanan untuk menentang perubahan medan coil","Tegak lurus terhadap permukaan material","Acak tergantung suhu material"]', 1,
   'Hukum Lenz menyatakan eddy current mengalir berlawanan untuk menentang perubahan medan magnet asalnya; medan oposisi inilah yang mengubah impedansi coil dan terdeteksi sebagai sinyal. Arahnya tidak searah, tidak tegak lurus, dan tidak acak.', 'Prinsip Dasar', 'medium'),
  ('Rumus standar kedalaman penetrasi (skin depth) yang diajarkan di modul (f dalam kHz, sigma dalam %IACS, mu_r relatif) adalah...',
   '["delta ~ 21 / akar(f x sigma x mu_r) mm","delta ~ 21 x f x sigma x mu_r mm","delta ~ akar(f x sigma x mu_r) / 21 mm","delta ~ 21 / (f + sigma + mu_r) mm"]', 0,
   'Skin depth standar delta ~ 21/akar(f x sigma x mu_r) mm; penetrasi berbanding terbalik dengan akar dari frekuensi, konduktivitas, dan permeabilitas. Bentuk perkalian langsung atau penjumlahan tidak benar.', 'Fisika ET', 'medium'),
  ('Sesuai rumus skin depth, jika frekuensi pengujian DINAIKKAN maka kedalaman penetrasi eddy current akan...',
   '["Bertambah dalam","Berkurang/lebih dangkal","Tidak berubah","Menjadi nol seketika"]', 1,
   'Karena delta berbanding terbalik dengan akar f, menaikkan frekuensi memperkecil skin depth sehingga penetrasi lebih dangkal namun sensitivitas permukaan meningkat. Penetrasi tidak bertambah dan tidak konstan.', 'Fisika ET', 'medium'),
  ('Untuk deteksi crack di PERMUKAAN dengan sensitivitas tinggi, rentang frekuensi yang paling tepat adalah...',
   '["Frekuensi sangat rendah (<1 kHz)","DC (arus searah)","Frekuensi tinggi (>1 MHz)","Tanpa frekuensi sama sekali"]', 2,
   'Frekuensi tinggi (>1 MHz) memberi sensitivitas tinggi terhadap cacat permukaan meski penetrasi dangkal (<0,5 mm), sehingga cocok untuk crack permukaan. Frekuensi rendah cocok untuk penetrasi dalam, dan DC tidak menghasilkan medan bergetar.', 'Fisika ET', 'medium'),
  ('Mengapa memilih frekuensi RENDAH (<10 kHz) berguna dalam inspeksi tertentu?',
   '["Memberi penetrasi lebih dalam untuk near-surface defect, walau sensitivitas turun","Menghasilkan sensitivitas permukaan tertinggi","Menghilangkan kebutuhan kalibrasi","Membuat probe tidak peka lift-off"]', 0,
   'Frekuensi rendah memperbesar skin depth sehingga penetrasi lebih dalam (untuk near-surface defect), namun konsekuensinya sensitivitas menurun. Frekuensi rendah bukan untuk sensitivitas permukaan tertinggi dan tidak menghapus kalibrasi maupun lift-off.', 'Fisika ET', 'medium'),
  ('Perbedaan utama konfigurasi DIFFERENTIAL dan ABSOLUTE pada bobbin probe adalah...',
   '["Differential tidak butuh kalibrasi; absolute butuh","Differential hanya untuk plastik; absolute untuk logam","Differential memakai dua coil yang membaca selisih (peka defect kecil/lokal); absolute satu coil (peka perubahan gradual)","Keduanya identik, hanya beda merek"]', 2,
   'Differential menggunakan dua coil yang membaca beda sehingga peka terhadap defect kecil/lokal seperti pitting; absolute menggunakan satu coil yang cocok mendeteksi perubahan gradual seperti wall thinning. Keduanya tetap butuh kalibrasi dan hanya untuk material konduktif.', 'Probe', 'medium'),
  ('Keunggulan utama ARRAY probe dibanding single-coil probe adalah...',
   '["Lebih murah secara elektronik","Tidak terpengaruh konduktivitas material","Memindai area lebar dalam satu pass dengan resolusi tinggi","Tidak perlu balance/kalibrasi"]', 2,
   'Array probe menyusun banyak coil sehingga memindai area lebar dalam satu pass dengan resolusi tinggi (boost produktivitas). Kelemahannya justru lebih mahal, dan tetap dipengaruhi konduktivitas serta memerlukan kalibrasi.', 'Probe', 'medium'),
  ('Probe modern dapat menghilangkan sinyal lift-off secara otomatis dengan teknik...',
   '["Two-frequency atau lift-off mixing","Menambah panjang kabel","Mencelupkan probe ke air","Memperbesar diameter coil 10x"]', 0,
   'Two-frequency atau lift-off mixing dapat membatalkan sinyal lift-off secara otomatis pada instrumen modern. Memanjangkan kabel, mencelup ke air, atau memperbesar coil bukan metode kompensasi lift-off.', 'Probe', 'medium'),
  ('Pada impedance plane, parameter yang membedakan sinyal CRACK dari sinyal LIFT-OFF adalah...',
   '["Panjang kabel probe","Phase angle (sudut fasa)","Warna layar instrumen","Nomor seri probe"]', 1,
   'Crack dan lift-off bergerak ke arah/sudut yang berbeda di impedance plane, sehingga phase angle digunakan untuk membedakan keduanya. Panjang kabel, warna layar, dan nomor seri tidak relevan untuk diskriminasi sinyal.', 'Impedance Plane', 'medium'),
  ('Tujuan melakukan PHASE ROTATION pada instrumen ET modern adalah...',
   '["Menaikkan tegangan baterai","Mengubah material menjadi konduktif","Meng-align sinyal lift-off ke horizontal sehingga sinyal defect tampil vertikal/lebih jelas","Menghapus kebutuhan reference standard"]', 2,
   'Phase rotation memutar fasa agar sinyal lift-off sejajar horizontal, sehingga sinyal defect muncul vertikal dan lebih mudah dibaca sebagai sinyal murni. Rotasi fasa tidak mengubah baterai, material, atau menghapus reference standard.', 'Impedance Plane', 'medium'),
  ('Sebelum scanning, probe perlu di-BALANCE. Balance dilakukan dengan menempatkan probe di...',
   '["Tepat di atas notch terdalam","Area tanpa defect (reference) agar operating point ke center display","Di atas support plate","Di atas pit yang paling dalam"]', 1,
   'Balance dilakukan di area no-defect sehingga operating point berada di center display sebagai titik nol acuan. Menempatkan probe di notch, pit, atau support plate justru memasukkan sinyal defect/geometrik ke titik balance.', 'Kalibrasi', 'medium'),
  ('Dalam urutan kalibrasi ET, setelah balance probe, gain diatur sehingga sinyal dari notch reference mencapai amplitudo predetermined yang tipikalnya...',
   '["20% FSH","50% FSH","80% FSH","120% FSH"]', 2,
   'Gain diatur agar sinyal dari notch reference mencapai amplitudo tipikal 80% FSH (full screen height) sesuai prosedur. 20% dan 50% terlalu rendah, sedangkan 120% melebihi skala layar.', 'Kalibrasi', 'medium'),
  ('Menurut ASME V, verifikasi kalibrasi (mid-shift) ET tipikal dilakukan...',
   '["Setiap 4 jam atau saat pergantian operator","Sekali per tahun","Hanya jika ditemukan defect","Setiap 30 detik"]', 0,
   'ASME V menetapkan verifikasi kalibrasi setiap 4 jam atau saat operator berganti. Sekali setahun terlalu jarang, hanya saat ditemukan defect tidak menjamin validitas, dan tiap 30 detik tidak praktis.', 'Kalibrasi', 'medium'),
  ('Pada inspeksi heat exchanger, pull rate (kecepatan tarik) bobbin probe yang tipikal adalah...',
   '["10-20 m/s secepat mungkin","0,5-1 m/s dan dijaga konstan","Tidak penting, boleh berubah-ubah","Hanya 1 mm/jam"]', 1,
   'Pull rate bobbin probe tipikal 0,5-1 m/s dan harus konstan; kecepatan yang tidak konsisten menimbulkan artifact sinyal. Kecepatan terlalu tinggi atau berubah-ubah merusak interpretasi, dan 1 mm/jam tidak praktis.', 'Teknik', 'medium'),
  ('Pada banyak prosedur tubing, pit dengan kedalaman melebihi ambang tertentu memerlukan tindakan plug/repair. Ambang yang umum diajarkan adalah kedalaman...',
   '[">10% wall",">40% wall",">90% wall",">5% wall"]', 1,
   'Pit yang lebih dalam dari 40% ketebalan dinding (>40% wall) umumnya memerlukan repair/plug sesuai materi. Ambang 10% atau 5% terlalu konservatif untuk batas ini, sedangkan menunggu hingga 90% terlalu berbahaya.', 'Acceptance', 'medium'),
  ('Standar internasional yang khusus mengatur pengujian eddy current adalah...',
   '["ISO 9712","ISO 15549","ISO 9001","ISO 14001"]', 1,
   'ISO 15549 adalah standar internasional untuk pengujian eddy current. ISO 9712 mengatur kualifikasi & sertifikasi personel NDT, ISO 9001 sistem manajemen mutu, dan ISO 14001 manajemen lingkungan.', 'Kode & Standar', 'medium'),
  ('Pada 100 kHz aluminum (sigma=40%IACS, mu_r=1), skin depth dengan delta ~ 21/akar(f x sigma x mu_r) kira-kira sebesar...',
   '["~ 3,3 mm","~ 0,33 mm","~ 33 mm","~ 0,03 mm"]', 1,
   'delta ~ 21/akar(100x40x1) = 21/akar(4000) ~ 21/63,2 ~ 0,33 mm, sesuai contoh modul. Nilai lain berbeda satu hingga dua orde dari hasil yang benar.', 'Fisika ET', 'hard'),
  ('Mengapa baja (steel) memiliki skin depth jauh lebih kecil daripada aluminum pada frekuensi yang sama?',
   '["Karena baja tidak konduktif","Karena permeabilitas relatif (mu_r) baja jauh lebih besar","Karena baja lebih ringan","Karena baja tidak ferromagnetik"]', 1,
   'Baja ferromagnetik punya mu_r tinggi (mis. ~100); karena delta berbanding terbalik dengan akar mu_r, skin depth-nya jadi sangat kecil (mis. ~0,07 mm pada 100 kHz). Baja justru konduktif dan ferromagnetik, dan beratnya tidak relevan dengan skin depth.', 'Fisika ET', 'hard'),
  ('Pada teknik MIXING dua-frekuensi, sinyal support plate dan lift-off dapat dihilangkan dengan cara...',
   '["Mengurangkan reference channel dari signal channel sehingga tersisa display defect-only","Menjumlahkan amplitudo semua channel","Mengalikan frekuensi dengan suhu","Menonaktifkan operating point"]', 0,
   'Mixing two-frequency mengurangkan reference channel dari signal channel untuk membatalkan sinyal lift-off dan support plate, menyisakan tampilan defect-only. Menjumlahkan amplitudo atau mengalikan frekuensi-suhu bukan cara mixing.', 'Impedance Plane', 'hard'),
  ('Jika verifikasi kalibrasi mid-shift GAGAL (kalibrasi tidak valid), tindakan yang benar adalah...',
   '["Lanjut scanning karena hasil sebelumnya pasti benar","Recalibrate dari awal dan re-scan semua weld/tube sejak last good calibration","Menaikkan gain hingga sinyal kembali muncul lalu lanjut","Mengabaikan dan menandatangani laporan"]', 1,
   'Jika verifikasi gagal, harus recalibrate dari awal dan re-scan semua weld/tube sejak kalibrasi valid terakhir karena hasil di antaranya diragukan. Melanjutkan, menaikkan gain sembarangan, atau mengabaikan akan membuat hasil tidak andal.', 'Kalibrasi', 'hard'),
  ('Pada impedance plane, perbedaan material atau temper (kondisi metalurgi) akan menggeser titik sinyal di sepanjang...',
   '["Lift-off line","Conductivity curve","Sumbu waktu","Garis dosis"]', 1,
   'Perubahan konduktivitas akibat beda material atau temper menggeser sinyal sepanjang conductivity curve. Lift-off line khusus untuk perubahan jarak probe, dan sumbu waktu/dosis tidak ada pada impedance plane.', 'Impedance Plane', 'hard'),
  ('Pada interpretasi tubing, sinyal kuat yang muncul di ujung tube (tube end / tube sheet) sebaiknya...',
   '["Dikenali sebagai end signal yang berbeda signature-nya dari pit di mid-tube","Langsung dianggap pit terdalam","Diabaikan sepenuhnya tanpa evaluasi","Dihitung sebagai support plate baru"]', 0,
   'Ujung tube (tube sheet) menghasilkan sinyal kuat dengan signature berbeda dari pit di tengah tube, sehingga harus dikenali sebagai end signal agar tidak salah diklasifikasikan. Menganggapnya langsung sebagai pit, mengabaikannya, atau menyebutnya support plate adalah keliru.', 'Interpretasi', 'hard'),
  ('Untuk mengkuantifikasi wall loss UMUM (general/gradual) pada tubing, teknik yang paling tepat adalah...',
   '["Hanya melihat warna tube","Sengaja menambah lift-off","Multi-frequency mixing","Mematikan threshold"]', 2,
   'Wall loss umum berupa sinyal lebar bertahap dan paling tepat dikuantifikasi dengan multi-frequency mixing yang membantu memisahkan kontribusi geometri dari penipisan. Melihat warna, menambah lift-off, atau mematikan threshold tidak mengukur penipisan dinding.', 'Interpretasi', 'hard'),
  ('Sebuah pit kecil yang sangat terlokalisasi berisiko TERLEWAT (under-call) jika diinspeksi memakai probe absolute. Penjelasan paling tepat adalah...',
   '["Probe absolute hanya bisa membaca material non-konduktif","Probe absolute peka terhadap perubahan gradual/drift sehingga indikasi lokal kecil bisa tenggelam, sedangkan differential lebih unggul untuk defect lokal","Probe absolute tidak memerlukan kalibrasi sehingga selalu salah","Probe absolute hanya bekerja pada frekuensi DC"]', 1,
   'Absolute (satu coil) responsif terhadap perubahan gradual dan rentan drift (mis. akibat suhu), sehingga indikasi lokal kecil seperti pit dapat tenggelam; differential (dua coil) membaca selisih lokal sehingga lebih unggul mendeteksi defect kecil/terlokalisasi. Absolute tetap untuk material konduktif, memerlukan kalibrasi, dan bekerja dengan AC.', 'Probe', 'hard')
) AS q(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L1' AND m."orderIndex" = 9 AND ls."orderIndex" = 2 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

